{"content": "1|// ─── TAD DOOH Player — SyncManager ───
2|// Manages the full sync cycle: manifest download, delta comparison,
3|// heartbeat pulse, and Supabase Realtime WAKE_UP_CALL listener.
4|
5|import type { MediaAsset, DeviceSyncPayload, DeviceCommand, SyncManifest, CampaignSchedule } from './types';
6|import { CacheManager } from './cache-manager';
7|import { PlaybackQueue } from './playback-queue';
8|import env from './config';
9|
10|export class SyncManager {
11|  private deviceId: string = '';
12|  private lastSyncHash: string = '';
13|  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
14|  private syncTimer: ReturnType<typeof setInterval> | null = null;
15|  private cacheManager: CacheManager;
16|  private playbackQueue: PlaybackQueue;
17|  private isOnline: boolean = navigator.onLine;
18|  private onPlaylistUpdate: (assets: MediaAsset[], schedules: CampaignSchedule[]) => void;
19|  private onKillSwitch: (reason: string) => void;
20|  private onCommands: (commands: DeviceCommand[]) => void;
21|
22|  constructor(
23|    cacheManager: CacheManager,
24|    playbackQueue: PlaybackQueue,
25|    callbacks: {
26|      onPlaylistUpdate: (assets: MediaAsset[], schedules: CampaignSchedule[]) => void;
27|      onKillSwitch: (reason: string) => void;
28|      onCommands: (commands: DeviceCommand[]) => void;
29|    }
30|  ) {
31|    this.cacheManager = cacheManager;
32|    this.playbackQueue = playbackQueue;
33|    this.onPlaylistUpdate = callbacks.onPlaylistUpdate;
34|    this.onKillSwitch = callbacks.onKillSwitch;
35|    this.onCommands = callbacks.onCommands;
36|  }
37|
38|  init(deviceId: string): void {
39|    this.deviceId = deviceId;
40|    this.playbackQueue.init(deviceId);
41|    this.setupNetworkListeners();
42|    this.executeFullSync();
43|    this.startHeartbeatLoop();
44|    this.startSyncLoop();
45|    this.setupRealtimeListener();
46|  }
47|
48|  destroy(): void {
49|    if (this.heartbeatTimer) clearInterval(this.heartbeatTimer);
50|    if (this.syncTimer) clearInterval(this.syncTimer);
51|    this.playbackQueue.destroy();
52|  }
53|
54|  async executeFullSync(): Promise<void> {
55|    if (!this.isOnline || !this.deviceId) return;
56|
57|    try {
58|      const payload: DeviceSyncPayload = await this.postDeviceSync();
59|
60|      // Kill-switch check
61|      if (payload.blocked) {
62|        const reason = payload.reason || 'awaiting_approval';
63|        this.onKillSwitch(reason);
64|        return;
65|      }
66|
67|      // Delta check — no update needed
68|      if (!payload.update) {
69|        console.log('[SyncManager] Delta sync matches. No update needed.');
70|        return;
71|      }
72|
73|      // Process commands
74|      if (payload.commands && payload.commands.length > 0) {
75|        this.onCommands(payload.commands);
76|        // Acknowledge commands
77|        for (const cmd of payload.commands) {
78|          this.acknowledgeCommand(cmd.id).catch(() => { });
79|        }
80|      }
81|
82|      // Download + cache new assets
83|      const assets = payload.media_assets || payload.videos || [];
84|      if (assets.length > 0) {
85|        const result = await this.cacheManager.cacheVideos(assets);
86|        console.log(`[SyncManager] Cached ${result.cached}/${assets.length} assets (${result.failed} failed)`);
87|        await this.cacheManager.evictStaleAssets(assets);
88|      }
89|
90|      this.lastSyncHash = payload.sync_hash;
91|      this.onPlaylistUpdate(assets, []);
92|    } catch (err) {
93|      console.error('[SyncManager] Full sync failed:', err);
94|    }
95|  }
96|
97|  async executeManifestSync(): Promise<void> {
98|    if (!this.isOnline || !this.deviceId) return;
99|
100|    try {
101|      const response = await fetch(`${env.API_URL}/sync/${this.deviceId}`);
102|      if (!response.ok) throw new Error(`HTTP ${response.status}`);
103|
104|      const manifest: SyncManifest = await response.json();
105|
106|      // Kill-switch from manifest
107|      if (manifest.killSwitch) {
108|        this.onKillSwitch(manifest.killSwitchReason || 'SUBSCRIPTION_UNPAID');
109|        return;
110|      }
111|
112|      // ETag comparison
113|      if (manifest.etag === this.lastSyncHash) {
114|        console.log('[SyncManager] Manifest ETag matches. No update.');
115|        return;
116|      }
117|
118|      const assets = manifest.playlist || [];
119|      if (assets.length > 0) {
120|        const result = await this.cacheManager.cacheVideos(assets);
121|        console.log(`[SyncManager] Manifest cached ${result.cached}/${assets.length} assets`);
122|        await this.cacheManager.evictStaleAssets(assets);
123|      }
124|
125|      this.lastSyncHash = manifest.etag;
126|      this.onPlaylistUpdate(assets, manifest.schedules || []);
127|    } catch (err) {
128|      console.error('[SyncManager] Manifest sync failed:', err);
129|    }
130|  }
131|
132|  private async postDeviceSync(): Promise<DeviceSyncPayload> {
133|    const response = await fetch(`${env.API_URL}/device/sync`, {
134|      method: 'POST',
135|      headers: { 'Content-Type': 'application/json' },
136|      body: JSON.stringify({
137|        deviceId: this.deviceId,
138|        lastHash: this.lastSyncHash,
139|      }),
140|    });
141|
142|    if (response.status === 402) {
143|      // Payment required — kill-switch
144|      return {
145|        update: false,
146|        blocked: true,
147|        sync_hash: '',
148|        media_assets: [],
149|        reason: 'subscription_unpaid',
150|      };
151|    }
152|
153|    if (!response.ok) throw new Error(`HTTP ${response.status}`);
154|    return response.json();
155|  }
156|
157|  private startHeartbeatLoop(): void {
158|    this.heartbeatTimer = setInterval(() => {
159|      this.sendHeartbeat().catch(err => {
160|        console.warn('[SyncManager] Heartbeat error:', err);
161|      });
162|    }, env.HEARTBEAT_INTERVAL_MS);
163|  }
164|
165|  private startSyncLoop(): void {
166|    this.syncTimer = setInterval(() => {
167|      this.executeFullSync().catch(err => {
168|        console.warn('[SyncManager] Sync loop error:', err);
169|      });
170|    }, env.SYNC_INTERVAL_MS);
171|  }
172|
173|  private async sendHeartbeat(): Promise<void> {
174|    if (!this.isOnline || !this.deviceId) return;
175|
176|    try {
177|      const payload = {
178|        device_id: this.deviceId,
179|        battery_level: await this.getBatteryLevel(),
180|        player_status: (document.getElementById('tad-player') as HTMLVideoElement | null)?.paused ? 'paused' : 'playing',
181|        timestamp: new Date().toISOString(),
182|      };
183|
184|      await fetch(`${env.API_URL}/device/heartbeat`, {
185|        method: 'POST',
186|        headers: { 'Content-Type': 'application/json' },
187|        body: JSON.stringify(payload),
188|      });
189|    } catch {
190|      // Heartbeat is non-critical fire-and-forget
191|    }
192|  }
193|
194|  private async acknowledgeCommand(commandId: string): Promise<void> {
195|    try {
196|      await fetch(`${env.API_URL}/device/command/${commandId}/ack`, {
197|        method: 'POST',
198|        headers: { 'Content-Type': 'application/json' },
199|        body: JSON.stringify({ result: { acknowledged: true } }),
200|      });
201|    } catch { /* non-critical */ }
202|  }
203|
204|  private setupNetworkListeners(): void {
205|    window.addEventListener('online', () => {
206|      this.isOnline = true;
207|      console.log('[SyncManager] Network online — triggering immediate sync');
208|      this.executeFullSync();
209|      this.playbackQueue.flushQueue();
210|    });
211|
212|    window.addEventListener('offline', () => {
213|      this.isOnline = false;
214|      console.log('[SyncManager] Network offline — entering offline mode');
215|    });
216|  }
217|
218|  private setupRealtimeListener(): void {
219|    if (!env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) {
220|      console.warn('[SyncManager] Supabase Realtime not configured — relying on poll-based sync only');
221|      return;
222|    }
223|
224|    try {
225|      // Dynamic import to avoid bundling Supabase when not configured
226|      import('@supabase/supabase-js').then(({ createClient }) => {
227|        const client = createClient(env.SUPABASE_URL, env.SUPABASE_ANON_KEY);
228|        client
229|          .channel('fleet_sync')
230|          .on('broadcast', { event: 'WAKE_UP_CALL' }, (payload: Record<string, unknown>) => {
231|            console.log('[SyncManager] WAKE_UP_CALL received:', payload);
232|            this.executeFullSync();
233|          })
234|          .subscribe((status: string) => {
235|            console.log('[SyncManager] Realtime subscription status:', status);
236|          });
237|      }).catch(err => {
238|        console.warn('[SyncManager] Supabase import failed, Realtime disabled:', err);
239|      });
240|    } catch {
241|      console.warn('[SyncManager] Realtime listener setup failed');
242|    }
243|  }
244|
245|  private async getBatteryLevel(): Promise<number | undefined> {
246|    try {
247|      if ('getBattery' in navigator) {
248|        const battery = await (navigator as any).getBattery();
249|        return Math.round(battery.level * 100);
250|      }
251|    } catch { /* Battery API not available */ }
252|    return undefined;
253|  }
254|}
