{"content": "1|// ─── TAD DOOH Player — Main Entry Point ───
2|// Orchestrates all player subsystems: SyncManager, CacheManager,
3|// PlaylistEngine, PlaybackQueue, KillSwitch, FullyKiosk Bridge, and SW registration.
4|
5|import { CacheManager } from './cache-manager';
6|import { PlaybackQueue } from './playback-queue';
7|import { SyncManager } from './sync-manager';
8|import { PlaylistEngine } from './playlist-engine';
9|import { KillSwitchEnforcer } from './killswitch';
10|import { FullyKioskBridge } from './fullykiosk-bridge';
11|import type { MediaAsset, DeviceCommand, PlayerStatus, CampaignSchedule } from './types';
12|
13|// ── Device ID Resolution ──
14|function resolveDeviceId(): string {
15|  const urlParams = new URLSearchParams(window.location.search);
16|  const fromUrl = urlParams.get('deviceId') || urlParams.get('device_id');
17|  if (fromUrl) {
18|    localStorage.setItem('TAD_DEVICE_ID', fromUrl);
19|    return fromUrl;
20|  }
21|  const fromStorage = localStorage.getItem('TAD_DEVICE_ID');
22|  if (fromStorage) return fromStorage;
23|  console.error('[TAD Player] No deviceId found. Provide via URL param: ?deviceId=XXX');
24|  return '';
25|}
26|
27|// ── Initialize all subsystems ──
28|async function initPlayer(): Promise<void> {
29|  const deviceId = resolveDeviceId();
30|  if (!deviceId) {
31|    window.dispatchEvent(new CustomEvent('TAD_UI_TOAST', {
32|      detail: 'ERROR — DEVICE ID NOT FOUND',
33|    }));
34|    return;
35|  }
36|
37|  console.log(`[TAD Player] Initializing for device: ${deviceId}`);
38|
39|  // 1. Register Service Worker
40|  if ('serviceWorker' in navigator) {
41|    try {
42|      await navigator.serviceWorker.register('/sw.js', { scope: '/' });
43|      console.log('[TAD Player] Service Worker registered');
44|    } catch (err) {
45|      console.warn('[TAD Player] Service Worker registration failed:', err);
46|    }
47|  }
48|
49|  // 2. Initialize subsystems
50|  const cacheManager = new CacheManager();
51|  const playbackQueue = new PlaybackQueue();
52|  const killSwitch = new KillSwitchEnforcer();
53|  killSwitch.init();
54|
55|  const kioskBridge = new FullyKioskBridge();
56|  kioskBridge.init();
57|
58|  const playlistEngine = new PlaylistEngine(playbackQueue, (status: PlayerStatus) => {
59|    console.log(`[TAD Player] Status: ${status}`);
60|  });
61|  playlistEngine.init(deviceId);
62|
63|  const syncManager = new SyncManager(cacheManager, playbackQueue, {
64|    onPlaylistUpdate: (assets: MediaAsset[], schedules: CampaignSchedule[]) => {
65|      console.log(`[TAD Player] Playlist updated: ${assets.length} assets, ${schedules.length} schedules`);
66|      playlistEngine.setPlaylist(assets, schedules);
67|    },
68|    onKillSwitch: (reason: string) => {
69|      console.warn(`[TAD Player] Kill-switch activated: ${reason}`);
70|      killSwitch.activate(reason);
71|      kioskBridge.lockKiosk().catch(() => { });
72|    },
73|    onCommands: (commands: DeviceCommand[]) => {
74|      console.log(`[TAD Player] Commands received: ${commands.length}`);
75|      for (const cmd of commands) {
76|        if (cmd.type === 'FORCE_SYNC') {
77|          syncManager.executeFullSync();
78|        } else {
79|          // Delegate all other commands to FullyKiosk Bridge
80|          kioskBridge.handleCommand(cmd.type, cmd.params).then(success => {
81|            console.log(`[TAD Player] Command ${cmd.type} executed: ${success}`);
82|          }).catch(() => { });
83|        }
84|      }
85|    },
86|  });
87|  syncManager.init(deviceId);
88|
89|  // 3. Screen Wake Lock (fallback if FullyKiosk not available)
90|  requestWakeLock();
91|
92|  // 4. Visibility change handler (re-sync when tablet comes back to foreground)
93|  document.addEventListener('visibilitychange', () => {
94|    if (!document.hidden) {
95|      console.log('[TAD Player] Tab visible — triggering sync');
96|      syncManager.executeFullSync();
97|      playbackQueue.flushQueue();
98|      kioskBridge.screenOn().catch(() => { });
99|    }
100|  });
101|
102|  console.log('[TAD Player] ✅ All systems initialized');
103|}
104|
105|// ── Screen Wake Lock ──
106|async function requestWakeLock(): Promise<void> {
107|  try {
108|    if ('wakeLock' in navigator) {
109|      const wakeLock = await navigator.wakeLock.request('screen');
110|      console.log('[TAD Player] Screen Wake Lock acquired');
111|
112|      document.addEventListener('visibilitychange', async () => {
113|        if (!document.hidden && !wakeLock.released) {
114|          try {
115|            await navigator.wakeLock.request('screen');
116|          } catch { /* non-critical */ }
117|        }
118|      });
119|    }
120|  } catch {
121|    console.warn('[TAD Player] Wake Lock not available — relying on FullyKiosk');
122|  }
123|}
124|
125|// ── Boot ──
126|initPlayer().catch(err => {
127|  console.error('[TAD Player] Fatal initialization error:', err);
128|  window.dispatchEvent(new CustomEvent('TAD_UI_TOAST', {
129|    detail: 'ERROR FATAL — PLAYER INIT FAILED',
130|  }));
131|});
