{"content": "1|// ─── TAD DOOH Player — FullyKiosk Bridge ──
2|// Integration with FullyKiosk Browser's local REST API (default: http://localhost:1312)
3|// Enables remote control of the tablet: screen brightness, volume, kiosk lock,
4|// screen on/off, force reboot, and motion sensor management.
5|// Ref: https://www.fully-kiosk.com/#webinterface
6|
7|import env from './config';
8|
9|const KIOSK_BASE_URL = 'http://localhost:1312';
10|
11|interface KioskCommand {
12|  action: string;
13|  params?: Record<string, string | number>;
14|}
15|
16|export class FullyKioskBridge {
17|  private baseUrl: string;
18|  private isAvailable: boolean = false;
19|  private checkTimer: ReturnType<typeof setInterval> | null = null;
20|
21|  constructor() {
22|    // Override base URL via env var for non-default port or remote proxy
23|    this.baseUrl = env.KIOSK_URL || KIOSK_BASE_URL;
24|  }
25|
26|  init(): void {
27|    this.detectKiosk();
28|    this.startAvailabilityCheck();
29|  }
30|
31|  destroy(): void {
32|    if (this.checkTimer) {
33|      clearInterval(this.checkTimer);
34|      this.checkTimer = null;
35|    }
36|  }
37|
38|  isKioskAvailable(): boolean {
39|    return this.isAvailable;
40|  }
41|
42|  // ── Screen Management ──
43|  async setScreenBrightness(level: number): Promise<boolean> {
44|    // Level: 0-255 (Android brightness scale)
45|    return this.sendCommand({ action: 'setScreenBrightness', params: { level } });
46|  }
47|
48|  async screenOn(): Promise<boolean> {
49|    return this.sendCommand({ action: 'screenOn' });
50|  }
51|
52|  async screenOff(): Promise<boolean> {
53|    return this.sendCommand({ action: 'screenOff' });
54|  }
55|
56|  async keepScreenOn(enable: boolean): Promise<boolean> {
57|    return this.sendCommand({ action: enable ? 'enableScreenOn' : 'disableScreenOn' });
58|  }
59|
60|  // ── Volume Management ──
61|  async setVolume(level: number, stream: string = 'music'): Promise<boolean> {
62|    // Level: 0-15 (Android volume steps), stream: music/ring/alarm/notification
63|    return this.sendCommand({ action: 'setAudioVolume', params: { level, stream } });
64|  }
65|
66|  async setMute(mute: boolean): Promise<boolean> {
67|    return this.sendCommand({ action: mute ? 'setAudioMute' : 'setAudioUnmute' });
68|  }
69|
70|  // ── Kiosk Lock Management ──
71|  async lockKiosk(): Promise<boolean> {
72|    return this.sendCommand({ action: 'lockKiosk' });
73|  }
74|
75|  async unlockKiosk(): Promise<boolean> {
76|    return this.sendCommand({ action: 'unlockKiosk' });
77|  }
78|
79|  async isKioskLocked(): Promise<boolean> {
80|    const result = await this.sendQuery('isKioskLocked');
81|    return result === 'true';
82|  }
83|
84|  // ── Device Management ──
85|  async forceReboot(): Promise<boolean> {
86|    return this.sendCommand({ action: 'forceReboot' });
87|  }
88|
89|  async restartApp(): Promise<boolean> {
90|    return this.sendCommand({ action: 'restartApp' });
91|  }
92|
93|  async loadUrl(url: string): Promise<boolean> {
94|    return this.sendCommand({ action: 'loadStartUrl', params: { url } });
95|  }
96|
97|  // ── Motion Sensor (tablet proximity detection) ──
98|  async enableMotionSensor(): Promise<boolean> {
99|    return this.sendCommand({ action: 'enableMotionDetection' });
100|  }
101|
102|  async disableMotionSensor(): Promise<boolean> {
103|    return this.sendCommand({ action: 'disableMotionDetection' });
104|  }
105|
106|  async setMotionSensorSensitivity(level: number): Promise<boolean> {
107|    // Level: 0-100 (sensitivity scale)
108|    return this.sendCommand({ action: 'setMotionDetectionSensitivity', params: { level } });
109|  }
110|
111|  // ── Device Info Queries ──
112|  async getBatteryLevel(): Promise<number> {
113|    const result = await this.sendQuery('getBatteryLevel');
114|    return Number(result) || 0;
115|  }
116|
117|  async getDeviceId(): Promise<string> {
118|    const result = await this.sendQuery('getDeviceId');
119|    return String(result);
120|  }
121|
122|  async getNetworkInfo(): Promise<string> {
123|    return await this.sendQuery('getNetworkInfo') || '';
124|  }
125|
126|  // ── Process DeviceCommands from Backend ──
127|  async handleCommand(commandType: string, params: Record<string, unknown>): Promise<boolean> {
128|    switch (commandType) {
129|      case 'FORCE_SYNC':
130|        return true; // Handled by SyncManager, not by kiosk
131|      case 'SCREEN_ON':
132|        return this.screenOn();
133|      case 'SCREEN_OFF':
134|        return this.screenOff();
135|      case 'SET_BRIGHTNESS':
136|        return this.setScreenBrightness(Number(params.level || 128));
137|      case 'SET_VOLUME':
138|        return this.setVolume(Number(params.level || 10));
139|      case 'MUTE':
140|        return this.setMute(true);
141|      case 'UNMUTE':
142|        return this.setMute(false);
143|      case 'LOCK_KIOSK':
144|        return this.lockKiosk();
145|      case 'UNLOCK_KIOSK':
146|        return this.unlockKiosk();
147|      case 'REBOOT':
148|        return this.forceReboot();
149|      case 'RESTART_APP':
150|        return this.restartApp();
151|      case 'ENABLE_MOTION':
152|        return this.enableMotionSensor();
153|      case 'DISABLE_MOTION':
154|        return this.disableMotionSensor();
155|      default:
156|        console.warn(`[FullyKiosk] Unknown command type: ${commandType}`);
157|        return false;
158|    }
159|  }
160|
161|  // ── Internal: Send command to FullyKiosk REST API ──
162|  private async sendCommand(command: KioskCommand): Promise<boolean> {
163|    if (!this.isAvailable) return false;
164|
165|    try {
166|      const url = new URL(this.baseUrl);
167|      url.searchParams.set('cmd', command.action);
168|      if (command.params) {
169|        for (const [key, value] of Object.entries(command.params)) {
170|          url.searchParams.set(key, String(value));
171|        }
172|      }
173|
174|      const response = await fetch(url.toString());
175|      return response.ok;
176|    } catch {
177|      return false;
178|    }
179|  }
