181|  private async sendQuery(action: string): Promise<string | null> {
182|    if (!this.isAvailable) return null;
183|
184|    try {
185|      const url = new URL(this.baseUrl);
186|      url.searchParams.set('cmd', action);
187|      const response = await fetch(url.toString());
188|      if (response.ok) {
189|        return await response.text();
190|      }
191|      return null;
192|    } catch {
193|      return null;
194|    }
195|  }
