197|  // ── Detect if FullyKiosk Browser is running ──
198|  private async detectKiosk(): Promise<void> {
199|    try {
200|      const response = await fetch(`${this.baseUrl}?cmd=isKioskLocked`, {
201|        signal: AbortSignal.timeout(3000),
202|      });
203|      this.isAvailable = response.ok;
204|      if (this.isAvailable) {
205|        console.log('[FullyKiosk] ✅ Detected — kiosk API available at ' + this.baseUrl);
206|        // Acquire screen wake lock through kiosk
207|        this.keepScreenOn(true).catch(() => { });
208|        // Enable motion sensor for proximity-based screen wake
209|        this.enableMotionSensor().catch(() => { });
210|      } else {
211|        console.log('[FullyKiosk] ❌ Not detected — standard browser mode');
212|      }
213|    } catch {
214|      this.isAvailable = false;
215|      console.log('[FullyKiosk] ❌ Not detected — standard browser mode');
216|    }
217|  }
218|
219|  private startAvailabilityCheck(): void {
