{"content": "1|// ─── TAD DOOH Player — CacheManager ───
2|// IndexedDB-based video blob caching for offline resilience.
3|// Falls back to Cache API then network when IndexedDB is unavailable.
4|
5|import type { MediaAsset, CachedVideo } from './types';
6|import env from './config';
7|
8|const DB_NAME = 'tad_video_cache';
9|const DB_VERSION = 1;
10|const STORE_NAME = 'videos';
11|
12|export class CacheManager {
13|  private dbReady: Promise<IDBDatabase>;
14|
15|  constructor() {
16|    this.dbReady = this.openDB();
17|  }
18|
19|  private async openDB(): Promise<IDBDatabase> {
20|    return new Promise((resolve, reject) => {
21|      const request = indexedDB.open(DB_NAME, DB_VERSION);
22|      request.onupgradeneeded = () => {
23|        const db = request.result;
24|        if (!db.objectStoreNames.contains(STORE_NAME)) {
25|          db.createObjectStore(STORE_NAME, { keyPath: 'url' });
26|        }
27|      };
28|      request.onsuccess = () => resolve(request.result);
29|      request.onerror = () => reject(request.error);
30|    });
31|  }
32|
33|  async getVideoSource(asset: MediaAsset): Promise<string> {
34|    // 1. Check IndexedDB
35|    const cached = await this.getFromIndexedDB(asset.url);
36|    if (cached) {
37|      if (asset.checksum && cached.checksum !== asset.checksum) {
38|        // Integrity mismatch — evict stale entry
39|        await this.evict(asset.url);
40|      } else {
41|        return URL.createObjectURL(cached.blob);
42|      }
43|    }
44|
45|    // 2. Check Cache API (browser cache)
46|    try {
47|      const cache = await caches.open('tad-player-videos');
48|      const response = await cache.match(asset.url);
49|      if (response) {
50|        const blob = await response.blob();
51|        if (blob.size <= env.MAX_VIDEO_SIZE_BYTES) {
52|          await this.saveToIndexedDB(asset, blob);
53|          return URL.createObjectURL(blob);
54|        }
55|      }
56|    } catch {
57|      // Cache API unavailable — proceed to network
58|    }
59|
60|    // 3. Network fetch (online-only path)
61|    try {
62|      const response = await fetch(asset.url);
63|      if (!response.ok) throw new Error(`HTTP ${response.status}`);
64|      const blob = await response.blob();
65|      if (blob.size <= env.MAX_VIDEO_SIZE_BYTES) {
66|        await this.saveToIndexedDB(asset, blob);
67|        // Also store in Cache API for dual-layer resilience
68|        try {
69|          const cache = await caches.open('tad-player-videos');
70|          await cache.put(asset.url, new Response(blob));
71|        } catch { /* non-critical */ }
72|        return URL.createObjectURL(blob);
73|      }
74|    } catch (err) {
75|      console.error(`[CacheManager] Network fetch failed for ${asset.filename}:`, err);
76|      throw err;
77|    }
78|
79|    throw new Error(`No video source available for ${asset.filename}`);
80|  }
81|
82|  async cacheVideos(assets: MediaAsset[]): Promise<{ cached: number; failed: number }> {
83|    let cached = 0;
84|    let failed = 0;
85|
86|    for (const asset of assets) {
87|      try {
88|        const existing = await this.getFromIndexedDB(asset.url);
89|        if (existing && existing.checksum === asset.checksum) {
90|          cached++;
91|          continue; // Already cached and valid
92|        }
93|        await this.getVideoSource(asset); // Downloads + caches
94|        cached++;
95|      } catch {
96|        failed++;
97|      }
98|    }
99|
100|    return { cached, failed };
101|  }
102|
103|  async hasMissingAssets(assets: MediaAsset[]): Promise<boolean> {
104|    for (const asset of assets) {
105|      const cached = await this.getFromIndexedDB(asset.url);
106|      if (!cached || (asset.checksum && cached.checksum !== asset.checksum)) {
107|        return true;
108|      }
109|    }
110|    return false;
111|  }
112|
113|  async evictStaleAssets(currentAssets: MediaAsset[]): Promise<number> {
114|    const db = await this.dbReady;
115|    const tx = db.transaction(STORE_NAME, 'readonly');
116|    const store = tx.objectStore(STORE_NAME);
117|    const allKeys = await new Promise<string[]>(resolve => {
118|      const req = store.getAllKeys();
119|      req.onsuccess = () => resolve(req.result as string[]);
120|    });
121|
122|    const currentUrls = new Set(currentAssets.map(a => a.url));
123|    let evicted = 0;
124|
125|    for (const key of allKeys) {
126|      if (!currentUrls.has(key as string)) {
127|        await this.evict(key as string);
128|        evicted++;
129|      }
130|    }
131|    return evicted;
132|  }
133|
134|  private async getFromIndexedDB(url: string): Promise<CachedVideo | null> {
135|    const db = await this.dbReady;
136|    return new Promise(resolve => {
137|      const tx = db.transaction(STORE_NAME, 'readonly');
138|      const store = tx.objectStore(STORE_NAME);
139|      const req = store.get(url);
140|      req.onsuccess = () => resolve(req.result || null);
141|      req.onerror = () => resolve(null);
142|    });
143|  }
144|
145|  private async saveToIndexedDB(asset: MediaAsset, blob: Blob): Promise<void> {
146|    const db = await this.dbReady;
147|    return new Promise((resolve, reject) => {
148|      const tx = db.transaction(STORE_NAME, 'readwrite');
149|      const store = tx.objectStore(STORE_NAME);
150|      const entry: CachedVideo = {
151|        url: asset.url,
152|        blob,
153|        checksum: asset.checksum || asset.hashMd5 || 'no-checksum',
154|        cachedAt: Date.now(),
155|        size: blob.size,
156|      };
157|      const req = store.put(entry);
158|      req.onsuccess = () => resolve();
159|      req.onerror = () => reject(req.error);
160|    });
161|  }
162|
163|  private async evict(url: string): Promise<void> {
164|    const db = await this.dbReady;
165|    return new Promise(resolve => {
166|      const tx = db.transaction(STORE_NAME, 'readwrite');
167|      const store = tx.objectStore(STORE_NAME);
168|      const req = store.delete(url);
169|      req.onsuccess = () => resolve();
170|      req.onerror = () => resolve(); // Non-critical
171|    });
172|  }
173|}
