{"content": "1|// ─── TAD DOOH Player — PlaybackQueue ───
2|// Fire-and-forget queue for Proof of Play (PoP) confirmations.
3|// Uses the validated /telemetry/playback endpoint (not the deprecated /device/playback).
4|// Buffers events locally when offline, flushes on reconnect.
5|
6|import type { PlaybackEvent } from './types';
7|import env from './config';
8|
9|const QUEUE_DB_NAME = 'tad_playback_queue';
10|const QUEUE_DB_VERSION = 1;
11|const QUEUE_STORE = 'events';
12|
13|export class PlaybackQueue {
14|  private dbReady: Promise<IDBDatabase>;
15|  private flushTimer: ReturnType<typeof setInterval> | null = null;
16|  private deviceId: string = '';
17|
18|  constructor() {
19|    this.dbReady = this.openDB();
20|  }
21|
22|  init(deviceId: string): void {
23|    this.deviceId = deviceId;
24|    this.startFlushLoop();
25|  }
26|
27|  destroy(): void {
28|    if (this.flushTimer) {
29|      clearInterval(this.flushTimer);
30|      this.flushTimer = null;
31|    }
32|  }
33|
34|  async saveToQueue(event: PlaybackEvent): Promise<void> {
35|    const db = await this.dbReady;
36|    return new Promise((resolve, reject) => {
37|      const tx = db.transaction(QUEUE_STORE, 'readwrite');
38|      const store = tx.objectStore(QUEUE_STORE);
39|      const entry = {
40|        id: `${event.video_id}_${event.timestamp}`,
41|        ...event,
42|        device_id: this.deviceId || event.device_id,
43|        queuedAt: Date.now(),
44|      };
45|      const req = store.put(entry);
46|      req.onsuccess = () => resolve();
47|      req.onerror = () => reject(req.error);
48|    });
49|  }
50|
51|  async flushQueue(): Promise<{ sent: number; failed: number }> {
52|    const db = await this.dbReady;
53|    const events = await new Promise<PlaybackEvent[]>((resolve) => {
54|      const tx = db.transaction(QUEUE_STORE, 'readonly');
55|      const store = tx.objectStore(QUEUE_STORE);
56|      const req = store.getAll();
57|      req.onsuccess = () => resolve(req.result || []);
58|      req.onerror = () => resolve([]);
59|    });
60|
61|    if (events.length === 0) return { sent: 0, failed: 0 };
62|
63|    // Trim queue to max size (anti-OOM)
64|    if (events.length > env.PLAYBACK_QUEUE_MAX_SIZE) {
65|      const excess = events.length - env.PLAYBACK_QUEUE_MAX_SIZE;
66|      for (let i = 0; i < excess; i++) {
67|        await this.removeEvent(`${events[i].video_id}_${events[i].timestamp}`);
68|      }
69|      events.splice(0, excess);
70|    }
71|
72|    // Batch send — use the validated endpoint
73|    let sent = 0;
74|    let failed = 0;
75|
76|    try {
77|      const payload = events.map(e => ({
78|        deviceId: e.device_id,
79|        videoId: e.video_id,
80|        eventType: e.event_type === 'play_start' ? 'START' : e.event_type === 'play_confirm' ? 'END' : 'END',
81|        lat: e.lat,
82|        lng: e.lng,
83|        clientTimestamp: new Date(e.timestamp).toISOString(),
84|      }));
85|
86|      const response = await fetch(`${env.API_URL}/telemetry/playback-batch`, {
87|        method: 'POST',
88|        headers: { 'Content-Type': 'application/json' },
89|        body: JSON.stringify(payload),
90|      });
91|
92|      if (response.ok) {
93|        // Remove all successfully sent events
94|        for (const event of events) {
95|          await this.removeEvent(`${event.video_id}_${event.timestamp}`);
96|        }
97|        sent = events.length;
98|      } else {
99|        failed = events.length;
100|        console.warn(`[PlaybackQueue] Batch flush failed: HTTP ${response.status}`);
101|      }
102|    } catch (err) {
103|      failed = events.length;
104|      console.warn('[PlaybackQueue] Network error during flush:', err);
105|    }
106|
107|    return { sent, failed };
108|  }
109|
110|  private startFlushLoop(): void {
111|    this.flushTimer = setInterval(() => {
112|      this.flushQueue().catch(err => {
113|        console.error('[PlaybackQueue] Flush error:', err);
114|      });
115|    }, env.PLAYBACK_FLUSH_INTERVAL_MS);
116|  }
117|
118|  private async removeEvent(id: string): Promise<void> {
119|    const db = await this.dbReady;
120|    return new Promise(resolve => {
121|      const tx = db.transaction(QUEUE_STORE, 'readwrite');
122|      const store = tx.objectStore(QUEUE_STORE);
123|      const req = store.delete(id);
124|      req.onsuccess = () => resolve();
125|      req.onerror = () => resolve();
126|    });
127|  }
128|
129|  private async openDB(): Promise<IDBDatabase> {
130|    return new Promise((resolve, reject) => {
131|      const request = indexedDB.open(QUEUE_DB_NAME, QUEUE_DB_VERSION);
132|      request.onupgradeneeded = () => {
133|        const db = request.result;
134|        if (!db.objectStoreNames.contains(QUEUE_STORE)) {
135|          db.createObjectStore(QUEUE_STORE, { keyPath: 'id' });
136|        }
137|      };
138|      request.onsuccess = () => resolve(request.result);
139|      request.onerror = () => reject(request.error);
140|    });
141|  }
142|}
