{"content": "1|// ─── TAD DOOH Player — PlaylistEngine ───
2|// Manages the sequential video loop with intermission transitions,
3|// QR overlay, watchdog timer, and fallback behavior.
4|
5|import type { MediaAsset, PlayerStatus, CampaignSchedule } from './types';
6|import { PlaybackQueue } from './playback-queue';
7|import env from './config';
8|
9|const DAY_NAMES = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
10|
11|export class PlaylistEngine {
12|  private playlist: MediaAsset[] = [];
13|  private activePlaylist: MediaAsset[] = [];
14|  private currentIndex: number = 0;
15|  private schedules: CampaignSchedule[] = [];
16|  private videoElement: HTMLVideoElement | null = null;
17|  private playbackQueue: PlaybackQueue;
18|  private status: PlayerStatus = 'idle';
19|  private watchdogTimer: ReturnType<typeof setTimeout> | null = null;
20|  private deviceId: string = '';
21|  private onStatusChange?: (status: PlayerStatus) => void;
22|  private _scheduleCheckTimer: ReturnType<typeof setInterval> | null = null;
23|
24|  // DOM references
25|  private intermissionScreen: HTMLElement | null = null;
26|  private intermissionAdvertiserName: HTMLElement | null = null;
27|  private intermissionQr: HTMLImageElement | null = null;
28|  private intermissionTimerBar: HTMLElement | null = null;
29|  private qrContainer: HTMLElement | null = null;
30|
31|  constructor(playbackQueue: PlaybackQueue, onStatusChange?: (status: PlayerStatus) => void) {
32|    this.playbackQueue = playbackQueue;
33|    this.onStatusChange = onStatusChange;
34|  }
35|
36|  init(deviceId: string): void {
37|    this.deviceId = deviceId;
38|    this.videoElement = document.getElementById('tad-player') as HTMLVideoElement;
39|    this.intermissionScreen = document.getElementById('intermission-screen');
40|    this.intermissionAdvertiserName = document.getElementById('intermission-advertiser-name');
41|    this.intermissionQr = document.getElementById('intermission-qr') as HTMLImageElement;
42|    this.intermissionTimerBar = document.getElementById('intermission-timer-bar');
43|    this.qrContainer = document.getElementById('qr-container');
44|
45|    this.setupVideoEvents();
46|    this.startScheduleCheckLoop();
47|  }
48|
49|  setPlaylist(assets: MediaAsset[], schedules?: CampaignSchedule[]): void {
50|    if (assets.length === 0) {
51|      this.showFallback();
52|      return;
53|    }
54|
55|    this.playlist = assets;
56|    this.schedules = schedules || [];
57|    this.currentIndex = 0;
58|    this.rebuildActivePlaylist();
59|    this.playNext();
60|  }
61|
62|  getStatus(): PlayerStatus {
63|    return this.status;
64|  }
65|
66|  // ── Schedule-Aware Playlist Filter ──
67|  // Filters the master playlist to only include campaigns that should play NOW
68|  // based on their scheduleDays and scheduleHours settings.
69|  private rebuildActivePlaylist(): void {
70|    const now = new Date();
71|    const currentDay = DAY_NAMES[now.getDay()];
72|    const currentHour = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
73|
74|    if (this.schedules.length === 0) {
75|      // No scheduling data — play everything (legacy 24/7 behavior)
76|      this.activePlaylist = this.applyWeightedOrder(this.playlist);
77|      return;
78|    }
79|
80|    const eligibleCampaignIds = new Set<string>();
81|    for (const schedule of this.schedules) {
82|      const days = schedule.scheduleDays;
83|      const hours = schedule.scheduleHours;
84|
85|      // Empty/null schedule = always eligible (24/7)
86|      if (!days || days.length === 0) {
87|        eligibleCampaignIds.add(schedule.campaignId);
88|        continue;
89|      }
90|
91|      if (days.includes(currentDay)) {
92|        if (!hours || hours.length === 0) {
93|          eligibleCampaignIds.add(schedule.campaignId);
94|        } else {
95|          // Check if current hour falls within any hour range
96|          for (const hourRange of hours) {
97|            if (this.isHourInRange(currentHour, hourRange)) {
98|              eligibleCampaignIds.add(schedule.campaignId);
99|              break;
100|            }
101|          }
102|        }
103|      }
104|    }
105|
106|    const filtered = this.playlist.filter(a => eligibleCampaignIds.has(a.campaignId));
107|    this.activePlaylist = this.applyWeightedOrder(filtered.length > 0 ? filtered : this.playlist);
108|  }
109|
110|  private isHourInRange(current: string, range: string): boolean {
111|    // Supports "HH:MM" or "HH:MM-HH:MM" format
112|    if (range.includes('-')) {
113|      const [start, end] = range.split('-');
114|      return current >= start && current <= end;
115|    }
116|    return current >= range;
117|  }
118|
119|  private applyWeightedOrder(assets: MediaAsset[]): MediaAsset[] {
120|    // Weighted shuffle: assets with higher weight appear more frequently
121|    const maxWeight = Math.max(...assets.map(a => a.weight || 1));
122|    if (maxWeight <= 1) return assets; // No weighting needed
123|
124|    const weighted: MediaAsset[] = [];
125|    for (const asset of assets) {
126|      const repeatCount = asset.weight || 1;
127|      for (let i = 0; i < repeatCount; i++) {
128|        weighted.push(asset);
129|      }
130|    }
131|
132|    // Fisher-Yates shuffle for randomized weighted order
133|    for (let i = weighted.length - 1; i > 0; i--) {
134|      const j = Math.floor(Math.random() * (i + 1));
135|      [weighted[i], weighted[j]] = [weighted[j], weighted[i]];
136|    }
137|    return weighted;
138|  }
139|
140|  private startScheduleCheckLoop(): void {
141|    // Re-check schedule every 60 seconds to activate/deactivate campaigns
142|    this._scheduleCheckTimer = setInterval(() => {
143|      this.rebuildActivePlaylist();
144|      // If current video is no longer in active playlist, transition to next eligible
145|      if (this.activePlaylist.length > 0) {
146|        const currentAsset = this.activePlaylist[this.currentIndex];
147|        if (!this.activePlaylist.some(a => a.id === currentAsset?.id)) {
148|          this.currentIndex = 0;
149|          this.playNext();
150|        }
151|      }
152|    }, 60_000);
153|  }
154|
155|  private setupVideoEvents(): void {
156|    if (!this.videoElement) return;
157|
158|    this.videoElement.addEventListener('ended', () => this.handleTransition());
159|    this.videoElement.addEventListener('error', () => this.onPlaybackError());
160|    this.videoElement.addEventListener('stalled', () => this.resetWatchdog());
161|    this.videoElement.addEventListener('waiting', () => this.resetWatchdog());
162|  }
163|
164|  private playNext(): void {
165|    if (this.activePlaylist.length === 0 || !this.videoElement) return;
166|    if (window.tadKillSwitchActive) return;
167|
168|    const asset = this.activePlaylist[this.currentIndex];
169|    this.setStatus('playing');
170|    this.startWatchdog(asset.duration * 1000 + 5000); // duration + 5s buffer
171|
172|    // Generate QR URL for the current campaign
173|    const qrUrl = this.generateQrUrl(asset);
174|    if (qrUrl) {
175|      this.showQrOverlay(qrUrl);
176|    } else {
177|      this.hideQrOverlay();
178|    }
179|
180|    // Track playback start
181|    this.playbackQueue.saveToQueue({
182|      device_id: this.deviceId,
183|      video_id: asset.id,
184|      timestamp: Date.now(),
185|      event_type: 'play_start',
186|    });
187|
188|    // Set video source — the CacheManager will have already resolved to a blob URL
189|    this.videoElement.src = asset.url;
190|    this.videoElement.play().catch(err => {
191|      console.warn('[PlaylistEngine] Auto-play blocked:', err);
192|      // Retry with muted (bypass browser policy)
193|      this.videoElement!.muted = true;
194|      this.videoElement!.play().catch(() => this.onPlaybackError());
195|    });
196|  }
197|
198|  private handleTransition(): void {
199|    if (this.activePlaylist.length === 0) return;
200|
201|    const currentAsset = this.activePlaylist[this.currentIndex];
202|
203|    // Track playback completion (PoP — Proof of Play)
204|    this.playbackQueue.saveToQueue({
205|      device_id: this.deviceId,
206|      video_id: currentAsset.id,
207|      timestamp: Date.now(),
208|      event_type: 'play_confirm',
209|    });
210|
211|    // Advance index (wraps around the active playlist)
212|    this.currentIndex = (this.currentIndex + 1) % this.activePlaylist.length;
213|
214|    // Show intermission screen (5s transition with QR)
215|    this.showIntermission(currentAsset);
216|  }
217|
218|  private showIntermission(_previousAsset: MediaAsset): void {
219|    this.setStatus('intermission');
220|    this.clearWatchdog();
221|
222|    const nextAsset = this.activePlaylist[this.currentIndex];
223|    const nextAdvertiser = nextAsset.advertiserName || 'TAD';
224|    const nextQrUrl = this.generateQrUrl(nextAsset);
225|
226|    // Update intermission UI
227|    if (this.intermissionAdvertiserName) {
228|      this.intermissionAdvertiserName.textContent = nextAdvertiser;
229|    }
230|    if (this.intermissionQr && nextQrUrl) {
231|      this.intermissionQr.src = `https://api.qrserver.com/v1/create-qr-code/?size=380x380&data=${encodeURIComponent(nextQrUrl)}`;
232|    }
233|    if (this.intermissionScreen) {
234|      this.intermissionScreen.style.display = 'block';
235|    }
236|
237|    // Timer bar animation
238|    if (this.intermissionTimerBar) {
239|      this.intermissionTimerBar.style.width = '0%';
240|      requestAnimationFrame(() => {
241|        this.intermissionTimerBar!.style.width = '100%';
242|      });
243|    }
244|
245|    // Auto-advance after intermission duration
246|    setTimeout(() => {
247|      if (this.intermissionScreen) {
248|        this.intermissionScreen.style.display = 'none';
249|      }
250|      if (this.intermissionTimerBar) {
251|        this.intermissionTimerBar.style.width = '0%';
252|      }
253|      this.playNext();
254|    }, env.INTERMISSION_DURATION_MS);
255|  }
256|
257|  private showQrOverlay(qrUrl: string): void {
258|    if (!this.qrContainer) return;
259|    const img = this.qrContainer.querySelector('img');
260|    if (img) {
261|      img.src = `https://api.qrserver.com/v1/create-qr-code/?size=140x140&data=${encodeURIComponent(qrUrl)}`;
262|    }
263|    this.qrContainer.style.display = 'block';
264|  }
265|
266|  private hideQrOverlay(): void {
267|    if (this.qrContainer) {
268|      this.qrContainer.style.display = 'none';
269|    }
270|  }
271|
272|  private generateQrUrl(asset: MediaAsset): string | null {
273|    if (asset.qrUrl) return asset.qrUrl;
274|    // Build a TAD landing page URL from campaign metadata
275|    return null;
276|  }
277|
278|  private onPlaybackError(): void {
279|    console.error('[PlaylistEngine] Playback error on asset:', this.activePlaylist[this.currentIndex]?.filename);
280|    this.setStatus('error');
281|
282|    // Skip to next asset after a brief pause
283|    this.currentIndex = (this.currentIndex + 1) % this.activePlaylist.length;
284|    setTimeout(() => this.playNext(), 2000);
285|  }
286|
287|  private showFallback(): void {
288|    this.setStatus('idle');
289|    if (this.videoElement) {
290|      this.videoElement.src = '';
291|      this.videoElement.poster = '';
292|    }
293|    if (this.intermissionScreen) {
294|      this.intermissionScreen.style.display = 'none';
295|    }
296|    console.log('[PlaylistEngine] No playlist — showing fallback/idle');
297|  }
298|
299|  private startWatchdog(timeoutMs: number): void {
300|    this.clearWatchdog();
301|    this.watchdogTimer = setTimeout(() => {
302|      console.warn('[PlaylistEngine] Watchdog triggered — forcing transition');
303|      this.handleTransition();
304|    }, timeoutMs);
305|  }
306|
307|  private resetWatchdog(): void {
308|    if (this.watchdogTimer && this.activePlaylist.length > 0) {
309|      const asset = this.activePlaylist[this.currentIndex];
310|      this.startWatchdog(asset.duration * 1000 + 5000);
311|    }
312|  }
313|
314|  private clearWatchdog(): void {
315|    if (this.watchdogTimer) {
316|      clearTimeout(this.watchdogTimer);
317|      this.watchdogTimer = null;
318|    }
319|  }
320|
321|  private setStatus(status: PlayerStatus): void {
322|    this.status = status;
323|    this.onStatusChange?.(status);
324|  }
325|
326|  destroy(): void {
327|    this.clearWatchdog();
328|    if (this._scheduleCheckTimer) {
329|      clearInterval(this._scheduleCheckTimer);
330|      this._scheduleCheckTimer = null;
331|    }
332|  }
