{"content": "1|// ─── TAD DOOH Player — KillSwitch Enforcement ───
2|// Intercepts /device/sync responses to detect killSwitch directive.
3|// Persists state to localStorage for offline resilience.
4|// Displays full-screen overlay blocking all content playback.
5|
6|export class KillSwitchEnforcer {
7|  private active: boolean = false;
8|  private overlay: HTMLElement | null = null;
9|  private reasonEl: HTMLElement | null = null;
10|  private originalFetch: typeof window.fetch;
11|
12|  constructor() {
13|    this.overlay = document.getElementById('tad-killswitch-overlay');
14|    this.reasonEl = document.getElementById('tad-killswitch-reason');
15|    this.originalFetch = window.fetch.bind(window);
16|  }
17|
18|  init(): void {
19|    // Check cached killSwitch on load
20|    const cached = localStorage.getItem('TAD_KILLSWITCH_ACTIVE');
21|    if (cached) {
22|      try {
23|        const data = JSON.parse(cached);
24|        if (data && Date.now() - data.timestamp < 86_400_000) {
25|          this.activate(data.reason || 'SUBSCRIPTION_UNPAID');
26|        } else {
27|          localStorage.removeItem('TAD_KILLSWITCH_ACTIVE');
28|        }
29|      } catch {
30|        localStorage.removeItem('TAD_KILLSWITCH_ACTIVE');
31|      }
32|    }
33|
34|    // Intercept fetch to detect killSwitch in sync responses
35|    this.patchFetch();
36|  }
37|
38|  isActive(): boolean {
39|    return this.active;
40|  }
41|
42|  activate(reason: string): void {
43|    this.active = true;
44|    window.tadKillSwitchActive = true;
45|
46|    localStorage.setItem('TAD_KILLSWITCH_ACTIVE', JSON.stringify({
47|      reason,
48|      timestamp: Date.now(),
49|    }));
50|
51|    if (this.overlay) this.overlay.style.display = 'block';
52|    if (this.reasonEl) this.reasonEl.textContent = `Motivo: ${reason}`;
53|
54|    const player = document.getElementById('tad-player') as HTMLVideoElement;
55|    if (player) player.pause();
56|
57|    window.dispatchEvent(new CustomEvent('TAD_UI_TOAST', {
58|      detail: 'KILLSWITCH ACTIVO — SUSCRIPCION PENDIENTE',
59|    }));
60|  }
61|
62|  deactivate(): void {
63|    this.active = false;
64|    window.tadKillSwitchActive = false;
65|    localStorage.removeItem('TAD_KILLSWITCH_ACTIVE');
66|
67|    if (this.overlay) this.overlay.style.display = 'none';
68|  }
69|
70|  private patchFetch(): void {
71|    window.fetch = (input: RequestInfo | URL, init?: RequestInit) => {
72|      const url = typeof input === 'string' ? input : (input instanceof Request ? input.url : '');
73|
74|      return this.originalFetch(input, init).then(response => {
75|        if (typeof url === 'string' && (url.includes('/device/sync') || url.includes('/sync/'))) {
76|          const cloned = response.clone();
77|          cloned.json().then(data => {
78|            if (data.killSwitch === true) {
79|              this.activate(data.killSwitchReason || 'UNKNOWN');
80|            } else if (this.active) {
81|              this.deactivate();
82|            }
83|          }).catch(() => {});
84|        }
85|        return response;
86|      });
87|    };
88|  }
89|
90|  restoreFetch(): void {
91|    window.fetch = this.originalFetch;
92|  }
93|}
