{"content": "1|// ─── TAD DOOH Player — Service Worker ───
2|// Offline resilience: caches video assets, API responses, and the player shell.
3|// Enables playback even when the tablet loses connectivity for extended periods.
4|
5|/// <reference lib="webworker" />
6|
7|declare const self: ServiceWorkerGlobalScope;
8|
9|const CACHE_NAME = 'tad-player-v1';
10|const VIDEO_CACHE = 'tad-player-videos-v1';
11|const SHELL_CACHE = 'tad-player-shell-v1';
12|
13|const SHELL_ASSETS = [
14|  '/',
15|  '/index.html',
16|  '/assets/player.css',
17|];
18|
19|// Install: cache the shell assets
20|self.addEventListener('install', (event: ExtendableEvent) => {
21|  event.waitUntil(
22|    caches.open(SHELL_CACHE).then(cache => cache.addAll(SHELL_ASSETS))
23|  );
24|  self.skipWaiting();
25|});
26|
27|// Activate: clean up old caches
28|self.addEventListener('activate', (event: ExtendableEvent) => {
29|  event.waitUntil(
30|    caches.keys().then(keys =>
31|      Promise.all(
32|        keys.filter(key => key !== CACHE_NAME && key !== VIDEO_CACHE && key !== SHELL_CACHE)
33|          .map(key => caches.delete(key))
34|      )
35|    )
36|  );
37|  self.clients.claim();
38|});
39|
40|// Fetch: stale-while-revalidate for shell, cache-first for videos
41|self.addEventListener('fetch', (event: FetchEvent) => {
42|  const url = new URL(event.request.url);
43|
44|  // Video assets — cache-first (long-term cache, immutable)
45|  if (url.pathname.includes('/campaign-videos/') || url.pathname.endsWith('.mp4') || url.pathname.endsWith('.webm')) {
46|    event.respondWith(
47|      caches.open(VIDEO_CACHE).then(async cache => {
48|        const cached = await cache.match(event.request);
49|        if (cached) return cached;
50|
51|        const response = await fetch(event.request);
52|        if (response.ok) {
53|          cache.put(event.request, response.clone());
54|        }
55|        return response;
56|      })
57|    );
58|    return;
59|  }
60|
61|  // Supabase Storage — cache-first
62|  if (url.hostname.includes('supabase') && url.pathname.includes('/storage/')) {
63|    event.respondWith(
64|      caches.open(VIDEO_CACHE).then(async cache => {
65|        const cached = await cache.match(event.request);
66|        if (cached) return cached;
67|
68|        const response = await fetch(event.request);
69|        if (response.ok) {
70|          cache.put(event.request, response.clone());
71|        }
72|        return response;
73|      })
74|    );
75|    return;
76|  }
77|
78|  // API calls — network-first with cache fallback
79|  if (url.pathname.startsWith('/device/') || url.pathname.startsWith('/sync/') || url.pathname.startsWith('/telemetry/') || url.pathname.startsWith('/fleet/')) {
80|    event.respondWith(
81|      fetch(event.request)
82|        .then(response => {
83|          if (response.ok) {
84|            const clone = response.clone();
85|            caches.open(CACHE_NAME).then(cache => cache.put(event.request, clone));
86|          }
87|          return response;
88|        })
89|        .catch(() => caches.match(event.request) as Promise<Response>)
90|    );
91|    return;
92|  }
93|
94|  // Shell assets — stale-while-revalidate
95|  event.respondWith(
96|    caches.match(event.request).then(cached => {
97|      const fetchPromise = fetch(event.request).then(response => {
98|        if (response.ok) {
99|          caches.open(SHELL_CACHE).then(cache => cache.put(event.request, response.clone()));
100|        }
101|        return response;
102|      });
103|      return cached || fetchPromise;
104|    })
105|  );
106|});
