{"content": "1|import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|import { NotificationsService } from '../notifications/notifications.service';
4|import * as jwt from 'jsonwebtoken';
5|import * as crypto from 'crypto';
6|import { BUSINESS_RULES } from '../../common/constants/business-rules';
7|
8|const mediaAssetSafeSelect = {
9|  id: true,
10|  campaignId: true,
11|  type: true,
12|  filename: true,
13|  url: true,
14|  fileSize: true,
15|  checksum: true,
16|  duration: true,
17|  version: true,
18|  createdAt: true,
19|  qrUrl: true,
20|  weight: true,
21|};
22|
23|@Injectable()
24|export class SyncService {
25|  private readonly logger = new Logger(SyncService.name);
26|  private readonly JWT_SECRET = process.env.JWT_SECRET || 'tad-default-secret-2026';
27|
28|  constructor(
29|    private prisma: PrismaService,
30|    private notifications: NotificationsService
31|  ) { }
32|
33|  async getDeviceManifest(deviceId: string) {
34|    // 1. Validar hardware primero (Device)
35|    const device = await this.prisma.device.findUnique({
36|      where: { deviceId },
37|      include: { driver: true }
38|    });
39|
40|    if (!device) {
41|      await this.notifications.createAlert({
42|        title: 'Intento de Sincronización Fallido',
43|        message: `Un dispositivo desconocido (${deviceId}) intentó sincronizar contenido.`,
44|        type: 'WARNING',
45|        category: 'DEVICE',
46|        entityId: deviceId
47|      });
48|      throw new HttpException('DEVICE_NOT_FOUND_IN_CLUSTER', HttpStatus.NOT_FOUND);
49|    }
50|
51|    if (device.status !== BUSINESS_RULES.STATUS.DEVICE.ACTIVE) {
52|      await this.notifications.createAlert({
53|        title: 'Dispositivo Inactivo',
54|        message: `El dispositivo ${device.taxiNumber || deviceId} está intentando sincronizar pero su estado es ${device.status}.`,
55|        type: 'CRITICAL',
56|        category: 'DEVICE',
57|        entityId: deviceId
58|      });
59|      throw new HttpException('DEVICE_DEACTIVATED', HttpStatus.FORBIDDEN);
60|    }
61|
62|    // 2. Validar suscripción vía Driver o via Subscription entity
63|    const driver = device.driver;
64|
65|    // Si no hay driver, permitimos solo campañas GLOBALES (no segmentadas)
66|    // Esto es vital para el primer encendido (Out-of-the-box experience)
67|    const isDriverActive = driver && driver.status === BUSINESS_RULES.STATUS.DRIVER.ACTIVE;
68|    const isDriverPaid = (driver && driver.subscriptionPaid);
69|
70|    let hasValidSubscription = isDriverPaid;
71|
72|    if (!hasValidSubscription) {
73|      // Intentar ver si tiene suscripción activa en tabla subscriptions (independiente del driver)
74|      const sub = await this.prisma.subscription.findFirst({
75|        where: { deviceId }
76|      });
77|      hasValidSubscription = sub && sub.status === 'ACTIVE' && (!sub.validUntil || new Date() <= sub.validUntil);
78|    }
79|
80|    // ── VULN #1 PATCH (v12.1.2): Kill-Switch Directive ──
81|    // If driver is linked to this device and subscription is unpaid,
82|    // emit an explicit killSwitch directive that the PWA tablet MUST enforce.
83|    // This closes the offline-first paradox where the tablet never received the 402 kill signal.
84|    const shouldKillSwitch = driver && !hasValidSubscription;
85|
86|    if (shouldKillSwitch) {
87|      this.logger.warn(`🚨 [KILLSWITCH] Device ${deviceId} → Driver ${driver.id} subscription UNPAID. Emitting kill directive.`);
88|
89|      // Grace token with reduced TTL (1h, not 24h) to limit offline evasion window
90|      const graceToken = jwt.sign(
91|        {
92|          deviceId,
93|          taxi: device.taxiNumber,
94|          type: 'KILLSWITCH_GRACE',
95|          killSwitch: true,
96|          reason: 'SUBSCRIPTION_UNPAID',
97|          iat: Math.floor(Date.now() / 1000)
98|        },
99|        this.JWT_SECRET,
100|        { expiresIn: '1h' }
101|      );
102|
103|      // Manifest with killSwitch directive — empty playlist, no playable content
104|      return {
105|        timestamp: new Date().toISOString(),
106|        expiresAt: new Date(Date.now() + 3600 * 1000).toISOString(), // 1h TTL (reduced from 24h)
107|        etag: 'KILLSWITCH-402',
108|        killSwitch: true,
109|        killSwitchReason: 'SUBSCRIPTION_UNPAID',
110|        licenseToken: graceToken,
111|        device: {
112|          id: device.id,
113|          deviceId: device.deviceId,
114|          taxi: device.taxiNumber
115|        },
116|        count: 0,
117|        playlist: []
118|      };
119|    }
120|
121|    // 3. Obtener campañas activas
122|    const now = new Date();
123|    this.logger.log(`🕒 Sync [V5] Clock: ${now.toISOString()} | Device: ${deviceId}`);
124|
125|    let campaignFilter: any = { isGlobal: true }; // Fallback playlist por defecto
126|
127|    if (hasValidSubscription) {
128|      campaignFilter = {
129|        OR: [
130|          // 1. Canal Global (nacional — llega a TODOS los dispositivos con suscripción activa)
131|          // BUG FIX: antes requería targetCity:'Global', lo que exluía campañas con ciudad específica.
132|          { targetAll: true },
133|
134|          // 2. Canal Geofencing Ciudad (v1 y v2)
135|          ...(device.city ? [{ targetCity: device.city }] : []),
136|
137|          // 3. Canal Selectivo (Cities Array - v2): JSON array contains city
138|          ...(device.city ? [{
139|            targetCities: { contains: `"${device.city}"` }
140|          }] : []),
141|
142|          // 4. Canal de Flota (v2)
143|          ...(device.fleet ? [{
144|            targetFleets: { contains: `"${device.fleet}"` }
145|          }] : []),
146|
147|          // 5. Canal Directo (v2 UUID - asignación explícita por DeviceCampaign)
148|          { devices: { some: { device_id: device.id } } },
149|
150|          // 6. Canal Legacy (v1 Hardware ID)
151|          { targets: { some: { deviceId } } },
152|
153|          // 7. Canal Segmentado (v2 Segmentación por Conductor)
154|          ...(isDriverActive ? [
155|            { targetDrivers: { some: { id: driver.id } } }
156|          ] : []),
157|        ]
158|      };
159|    }
160|
161|    // 3. Obtener campañas activas via MASTER SYNC (Materialized View)
162|    // SRE Optimization: Pre-calculated targeting avoids complex joins in heartbeats.
163|    const city = device.city || 'Santiago';
164|
165|    const results: any[] = await this.prisma.$queryRaw`
166|      SELECT campaign_id FROM mv_active_campaigns
167|      WHERE active = true 
168|        AND start_date <= NOW() 
169|        AND end_date >= NOW()
170|        AND (
171|          target_all = true OR 
172|          target_city = ${city} OR
173|          target_cities::text LIKE ${`%${city}%`} OR
174|          assigned_device_uuids::jsonb @> ${JSON.stringify([device.id])}::jsonb OR
175|          assigned_hw_ids::jsonb @> ${JSON.stringify([deviceId])}::jsonb OR
176|          (assigned_driver_ids::jsonb @> ${JSON.stringify([driver?.id])}::jsonb AND ${!!isDriverActive})
177|        )
178|    `;
179|
180|    const campaignIds = results.map(r => r.campaign_id);
181|
182|    const activeCampaigns = await this.prisma.campaign.findMany({
183|      where: {
184|        id: { in: campaignIds }
185|      },
186|      include: {
187|        media: true,
188|        mediaAssets: { select: mediaAssetSafeSelect },
189|        videos: true
190|      }
191|    });
192|
193|    this.logger.log(`📊 Campaigns found (V5): ${activeCampaigns.length}`);
194|    activeCampaigns.forEach(c => {
195|      const assetsCount = (c.media?.length || 0) + (c.mediaAssets?.length || 0) + ((c as any).videos?.length || 0);
196|      this.logger.log(`   📂 Campaign "${c.name}" [${c.id}] | assets=${assetsCount} | dates: ${c.startDate.toISOString()} to ${c.endDate.toISOString()}`);
197|    });
198|
199|    // 3.5 Ordenar por prioridad (Revenue focus)
200|    activeCampaigns.sort((a, b) => (b.priority || 0) - (a.priority || 0));
201|
202|    const playlistMap = new Map<string, any>();
203|    activeCampaigns.forEach(c => {
204|      // Unificar Media, MediaAssets y Videos (v1, v2 y Hub)
205|      const mediaList = [
206|        ...(c.media || []),
207|        ...(c.mediaAssets || []),
208|        ...((c as any).videos || [])
209|      ];
210|
211|      mediaList.forEach((m: any) => {
212|        const key = m.hashMd5 || m.hash || m.checksum || m.url;
213|        if (!playlistMap.has(key)) {
214|          playlistMap.set(key, {
215|            id: m.id,
216|            campaignId: c.id,
217|            filename: m.filename || m.name || m.title || 'video.mp4',
218|            url: m.cdnUrl || m.url || '',
219|            checksum: m.hashMd5 || m.hash || m.checksum || 'no-checksum',
220|            hashMd5: m.hashMd5 || m.hash || m.checksum || null,
221|            duration: m.duration || m.durationSeconds || 30,
222|            version: new Date(c.updatedAt || new Date()).getTime(),
223|            priority: c.priority || 5
224|          });
225|        }
226|      });
227|    });
228|
229|    let playlist = Array.from(playlistMap.values());
230|    
231|    // 3.6 Limitar Slots (Regla de negocio estricta: 15 Máximo)
232|    playlist = playlist.slice(0, 15);
233|    
234|    // 3.7 Inyección de Cloudflare CDN
235|    playlist = playlist.map(item => {
236|       if (item.url && item.url.includes('supabase.co')) {
237|          item.url = item.url.replace(/https:\/\/[^\/]+\/storage\/v1\/object\/public/, 'https://media.tad.do');
238|       }
239|       return item;
240|    });
241|
242|    // 3.8 Calculate Manifest Hash for ETagging
243|    // Unique fingerprint based on campaign list and their last updates
244|    const manifestContent = activeCampaigns.map(c => `${c.id}-${c.updatedAt.getTime()}`).sort().join('|');
245|    const etag = crypto.createHash('md5').update(manifestContent).digest('hex');
246|
247|    // 4. Generar License Token (Kill-Switch)
248|    // El dispositivo solo puede reproducir contenido offline SI tiene este token válido.
249|    const licenseToken = jwt.sign(
250|      {
251|        deviceId,
252|        taxi: device.taxiNumber,
253|        type: 'OFFLINE_LICENSE',
254|        iat: Math.floor(Date.now() / 1000)
255|      },
256|      this.JWT_SECRET,
257|      { expiresIn: '24h' }
258|    );
259|
260|    // 5. Formatear manifiesto
261|    // Extract scheduling metadata for each campaign.
262|    // B2 PATCH: defensivo contra scheduleDays / scheduleHours corruptos.
263|    // Si el string es null o no es JSON parseable, degradamos a [] sin
264|    // romper el manifest entero (eso sería un 500 en todas las tablets).
265|    const safeJsonArray = (raw: string | null | undefined): string[] => {
266|      if (!raw) return [];
267|      try {
268|        const parsed = JSON.parse(raw);
269|        return Array.isArray(parsed) ? parsed : [];
270|      } catch (err) {
271|        this.logger.warn(
272|          `⚠️ [SYNC_V12.1.3] schedule JSON corrupto (${typeof raw}), degradando a []: ${(err as Error).message}`,
273|        );
274|        return [];
275|      }
276|    };
277|
278|    const schedules = activeCampaigns.map(c => ({
279|      campaignId: c.id,
280|      scheduleDays: safeJsonArray(c.scheduleDays as unknown as string | null),
281|      scheduleHours: safeJsonArray(c.scheduleHours as unknown as string | null),
282|      frequencyCap: c.frequencyCap || 0,
283|    }));
284|
285|    return {
286|      timestamp: new Date().toISOString(),
287|      expiresAt: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),
288|      etag,
289|      licenseToken,
290|      device: {
291|        id: device.id,
292|        deviceId: device.deviceId,
293|        taxi: device.taxiNumber
294|      },
295|      count: playlist.length,
296|      playlist,
297|      schedules
298|    };
299|  }
300|
301|  async refreshManifestView() {
302|    try {
303|      await this.prisma.$executeRaw`SELECT refresh_active_campaigns();`;
304|      this.logger.log('✅ Active Campaigns Materialized View Refreshed');
305|    } catch (e) {
306|      this.logger.error('❌ Failed to refresh Materialized View', e.stack);
307|    }
308|  }
