{"content": "1|import { Controller, Get, Param, Headers, HttpException, HttpStatus, Res } from '@nestjs/common';
2|import { SyncService } from './sync.service';
3|import { Public } from '../auth/decorators/public.decorator';
4|import { Response } from 'express';
5|
6|@Controller('sync')
7|export class SyncController {
8|  constructor(private readonly syncService: SyncService) {}
9|
10|  /**
11|   * GET /sync/:deviceId — Manifiesto de playlist + kill-switch.
12|   *
13|   * CAMBIO v12.1.3: cuando el servicio emite un manifest con `killSwitch:true`
14|   * (conductor moroso / sin suscripción activa), el endpoint responde HTTP 402
15|   * PAYMENT_REQUIRED en lugar de 200 con playlist vacía. La PWA del tablet y los
16|   * hooks `useBackgroundTelemetry`/`useTelemetry` se enteran del kill-switch
17|   * por código HTTP, no por inspección de payload (defensa en profundidad).
18|   *
19|   * El cuerpo del 402 sigue siendo el mismo manifest (incluye killSwitch, reason,
20|   * graceToken, expiresAt) para que cualquier cliente que inspeccione el body
21|   * también pueda tomar acción.
22|   */
23|  @Public()
24|  @Get(':deviceId')
25|  async getDeviceManifest(
26|    @Param('deviceId') deviceId: string,
27|    @Headers('if-none-match') ifNoneMatch: string,
28|    @Res({ passthrough: true }) res: Response,
29|  ) {
30|    if (!deviceId) {
31|      throw new HttpException('DEVICE_ID_REQUIRED', HttpStatus.BAD_REQUEST);
32|    }
33|
34|    const manifest = await this.syncService.getDeviceManifest(deviceId);
35|
36|    // ── KILL-SWITCH: 402 cuando el manifest marca bloqueo ──
37|    if ((manifest as any).killSwitch === true) {
38|      // Importante: NO fijar ETag en respuestas 402 para evitar
39|      // caching del estado de bloqueo por parte del cliente o proxy intermedio.
40|      res.setHeader('Cache-Control', 'no-store');
41|      throw new HttpException(manifest, HttpStatus.PAYMENT_REQUIRED);
42|    }
43|
44|    // Fast-path 304 Not Modified cuando el cliente tenía ETag actualizado
45|    if (ifNoneMatch && ifNoneMatch === manifest.etag) {
46|      res.status(HttpStatus.NOT_MODIFIED).send();
47|      return;
48|    }
49|
50|    res.setHeader('ETag', manifest.etag);
51|    res.setHeader('Cache-Control', 'public, max-age=0, must-revalidate');
52|    return manifest;
53|  }
