13|
14|const MAX_SLOTS_PER_DEVICE = 15;
15|
16|@Injectable()
17|export class DeviceService {
18|  private readonly logger = new Logger(DeviceService.name);
19|  private readonly JWT_SECRET = process.env.JWT_SECRET || 'tad-default-secret-2026';
20|
21|  constructor(
22|    private readonly prisma: PrismaService,
23|    private readonly campaignService: CampaignService,
24|    private readonly financeService: FinanceService,
25|  ) {}
26|
27|  /**
28|   * Calculates availability slots for a device.
29|   * Based on current dynamic playlist generation.
30|   */
31|  async getDeviceSlots(deviceId: string) {
32|    try {
33|      const device = await this.prisma.device.findUnique({ where: { deviceId } });
34|      if (!device) throw new Error('Device not found');
35|      
36|      const payload = await this.campaignService.getActiveSyncVideos(deviceId, device.city || 'Santiago');
37|      const occupied = payload.media_assets?.length || 0;
38|
39|      return {
40|        device_id: deviceId,
41|        max_slots: MAX_SLOTS_PER_DEVICE,
42|        assigned_slots: occupied,
43|        available_slots: Math.max(0, MAX_SLOTS_PER_DEVICE - occupied),
44|        usage_percentage: Math.round((occupied / MAX_SLOTS_PER_DEVICE) * 100)
45|      };
46|    } catch (error) {
47|      this.logger.warn(`⚠️ getDeviceSlots(${deviceId}): ${error?.message}`);
48|      return {
49|        device_id: deviceId,
50|        max_slots: MAX_SLOTS_PER_DEVICE,
51|        assigned_slots: 0,
52|        available_slots: MAX_SLOTS_PER_DEVICE,
53|        usage_percentage: 0
54|      };
55|    }
56|  }
57|
58|
59|  async registerDevice(dto: RegisterDeviceDto) {
60|    const existingDevice = await this.prisma.device.findUnique({
61|      where: { deviceId: dto.device_id },
62|    });
63|
64|    if (existingDevice) {
65|      this.logger.log(`Device already exists, updating lastSeen: ${dto.device_id}`);
66|      return this.prisma.device.update({
67|        where: { deviceId: dto.device_id },
68|        data: { 
69|          appVersion: dto.app_version,
70|          lastSeen: new Date(),
71|          driverId: dto.driver_id ?? undefined,
72|        },
73|      });
74|    }
75|
76|    this.logger.log(`Registering new device (PENDING approval): ${dto.device_id}`);
77|    return this.prisma.device.create({
78|      data: {
79|        deviceId: dto.device_id,
80|        appVersion: dto.app_version,
81|        status: BUSINESS_RULES.STATUS.DEVICE.INITIAL,          // 🔒 Requires admin approval before joining fleet
82|        lastSeen: new Date(),
83|        driverId: dto.driver_id,
84|      },
85|    });
86|  }
87|
88|  /** Returns all devices that have PENDING approval — for the admin dashboard. */
89|  async getPendingDevices() {
90|    return this.prisma.device.findMany({
91|      where: { status: BUSINESS_RULES.STATUS.DEVICE.INITIAL },
92|      orderBy: { lastSeen: 'desc' },
93|      select: { id: true, deviceId: true, appVersion: true, lastSeen: true },
94|    });
95|  }
96|
97|  /** Admin approves a device — sets it ACTIVE so it can join the fleet. */
98|  async approveDevice(deviceId: string) {
99|    this.logger.log(`✅ Admin approved device: ${deviceId}`);
100|    return this.prisma.device.update({
101|      where: { deviceId },
102|      data: { status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE },
103|    });
104|  }
105|
106|  /** Admin rejects/deletes a phantom device. */
107|  async rejectDevice(deviceId: string) {
108|    this.logger.warn(`🗑️ Admin rejected device: ${deviceId}`);
109|    return this.prisma.device.delete({ where: { deviceId } });
110|  }
111|
112|  async getFleetStatusSummary() {
113|    const now = new Date();
114|    const thirtyMinMs = 30 * 60 * 1000;
115|
116|    // SRE FIX: Single batch query — eliminates N+1 problem (getDeviceSlots per device)
117|    // Was timing out after 25s due to serial throttledMap(N devices × campaign joins).
118|    const [devices, campaignAssignments] = await Promise.all([
119|      // 1. Fetch all non-pending devices with minimal fields
120|      this.prisma.device.findMany({
121|        where: { status: { not: BUSINESS_RULES.STATUS.DEVICE.INITIAL } },
122|        select: {
123|          id: true,
124|          deviceId: true,
125|          taxiNumber: true,
126|          status: true,
127|          lastSeen: true,
128|          batteryLevel: true,
129|          playerStatus: true,
130|          city: true,
131|          driver: {
132|            select: { id: true, fullName: true, subscriptionPaid: true }
133|          }
134|        }
135|      }),
136|      // 2. Count campaign assignments per device in one query
137|      (this.prisma as any).deviceCampaign.groupBy({
138|        by: ['device_id'],
139|        _count: { campaign_id: true }
140|      }).catch(() => []) // Graceful fallback — table may not exist in all envs
141|    ]);
142|
143|    // Build a deviceId -> assignedCampaigns count map
144|    const slotMap = new Map<string, number>();
145|    for (const row of (campaignAssignments || [])) {
146|      slotMap.set(row.device_id, row._count?.campaign_id || 0);
147|    }
148|
149|    return devices.map((d) => {
150|      const isOnline = !!(d.lastSeen && (now.getTime() - d.lastSeen.getTime() <= thirtyMinMs));
151|      const assignedSlots = slotMap.get(d.id) || 0;
152|
153|      return {
154|        id: d.id,
155|        device_id: d.deviceId,
156|        deviceId: d.deviceId,
157|        taxi_number: d.taxiNumber,
158|        status: isOnline ? 'online' : (d.status === BUSINESS_RULES.STATUS.DEVICE.SUSPENDED ? 'inactive' : 'offline'),
159|        is_online: isOnline,
160|        battery_level: d.batteryLevel,
161|        occupied_slots: assignedSlots,
162|        available_slots: Math.max(0, MAX_SLOTS_PER_DEVICE - assignedSlots),
163|        max_slots: MAX_SLOTS_PER_DEVICE,
164|        player_status: d.playerStatus,
165|        last_seen: d.lastSeen,
166|        city: d.city || 'Santiago',
167|        driver: d.driver ? {
168|          id: d.driver.id,
169|          fullName: d.driver.fullName,
170|          subscriptionPaid: d.driver.subscriptionPaid
171|        } : null,
172|        driver_id: d.driver?.id || null,
173|        driver_name: d.driver?.fullName || 'No asignado',
174|        subscription_status: d.driver?.subscriptionPaid ? 'PAID' : 'PENDING'
175|      };
176|    });
177|  }
178|
179|  async deviceHeartbeat(dto: HeartbeatDto) {
180|    // SRE v12.1.1: Single query with driver included — eliminates N+1 (was 2 findUnique calls)
181|    let device = await this.prisma.device.findUnique({
182|      where: { deviceId: dto.device_id },
183|      include: { driver: true },
184|    });
185|
186|    if (!device) {
187|      // 🔒 Unknown device: register as PENDING (not ACTIVE) and block content
188|      this.logger.warn(`Heartbeat from unknown device: ${dto.device_id}. Registering as PENDING — awaiting admin approval.`);
189|      await this.prisma.device.create({
190|        data: {
191|          deviceId: dto.device_id,
192|          status: BUSINESS_RULES.STATUS.DEVICE.INITIAL,
193|          lastSeen: new Date(),
194|          batteryLevel: dto.battery_level,
195|          storageFree: dto.storage_free,
196|          playerStatus: dto.player_status,
197|        },
198|      });
199|      // Return blocked so the tablet does not receive content
200|      return { success: true, blocked: true, reason: 'awaiting_approval' };
201|    } else if (device.status === BUSINESS_RULES.STATUS.DEVICE.INITIAL) {
202|      // Device exists but is still awaiting admin approval
203|      this.logger.log(`⏳ Heartbeat from PENDING device: ${dto.device_id}. Awaiting admin approval.`);
204|      await this.prisma.device.update({
205|        where: { deviceId: dto.device_id },
206|        data: { lastSeen: new Date() },
207|      });
208|      return { success: true, blocked: true, reason: 'awaiting_approval' };
209|    } else {
210|      await this.prisma.device.update({
211|        where: { deviceId: dto.device_id },
212|        data: {
213|          lastSeen: new Date(),
214|          batteryLevel: dto.battery_level,
215|          storageFree: dto.storage_free,
216|          playerStatus: dto.player_status,
217|          lastLat: dto.lat ?? undefined,
218|          lastLng: dto.lng ?? undefined,
219|        },
220|      });
221|    }
222|    
223|    // SRE v12.1.1: Inline subscription check using already-loaded driver (no extra DB call)
224|    let blocked = false;
225|    let reason: string | undefined;
226|    
227|    if (device.driver) {
228|      const { driver } = device;
229|      if (driver.subscriptionPaid && (!driver.subscriptionEnd || driver.subscriptionEnd >= new Date())) {
230|        // Paid and valid — OK
231|      } else {
232|        // Expired or unpaid — log but DON'T block (per TAD policy)
233|        this.logger.warn(`⚠️ Device ${dto.device_id}: suscripción de ${driver.fullName} vencida o no pagada. Permitido por política TAD.`);
234|        // SRE: Fire-and-forget morosidad notification — does NOT block tablet response
235|        this.financeService.notifyMorosidad(dto.device_id).catch(e => {
236|          this.logger.error(`Failed to trigger morosidad notification for ${dto.device_id}: ${e.message}`);
237|        });
238|      }
239|    }
240|
241|    // SRE v12.1.1: Fire-and-forget heartbeat record — telemetry is NOT request-critical
242|    this.prisma.deviceHeartbeat.create({
243|      data: {
244|        deviceId: dto.device_id,
245|        batteryLevel: dto.battery_level,
246|        storageFree: dto.storage_free,
247|        timestamp: new Date(),
248|      },
249|    }).catch(e => {
250|      this.logger.error(`Failed to record heartbeat for ${dto.device_id}: ${e.message}`);
251|    });
252|
253|    this.logger.log(`💓 Heartbeat processed for device ${dto.device_id}. Battery: ${dto.battery_level}%, Player: ${dto.player_status}`);
254|    return { success: true, blocked, reason };
255|  }
256|
257|  private async checkSubscriptionStatus(deviceId: string) {
258|    const device = await this.prisma.device.findUnique({
259|      where: { deviceId },
260|      include: { driver: true }
261|    });
262|
263|    if (!device || !device.driver) {
264|      this.logger.log(`⚠️ Device ${deviceId}: Sin conductor vinculado (grace period).`);
265|      return { blocked: false, reason: undefined };
266|    }
267|
268|    const { driver } = device;
269|
270|    // [ACTUALIZADO]: Siempre permitir reproducción sin importar el estado de suscripción
271|    if (driver.subscriptionPaid && (!driver.subscriptionEnd || driver.subscriptionEnd >= new Date())) {
272|      return { blocked: false, reason: undefined };
273|    }
274|
275|    // Suscripción expirada o no pagada - Registramos pero NO bloqueamos
276|    this.logger.warn(`⚠️ Device ${deviceId}: suscripción de ${driver.fullName} vencida o no pagada. Permitido por política TAD.`);
277|    
278|    // Trigger notification para administración (opcional)
279|    try {
280|      await this.financeService.notifyMorosidad(deviceId);
281|    } catch (e) {
282|      this.logger.error(`Failed to trigger morosidad notification for ${deviceId}: ${e.message}`);
283|    }
284|
285|    return { blocked: false, reason: undefined }; // IMPORTANTE: Siempre desbloqueado
286|  }
287|
288|  /**
289|   * @deprecated Use TelemetryController's /telemetry/playback endpoint instead.
290|   * This method bypasses PoP (Proof of Play) validation, rate-limiting, and marks events as verified: false.
291|   * Scheduled for removal in v13.0.
292|   */
293|  async recordPlayback(dto: PlaybackConfirmationDto) {
294|    this.logger.log(`Playback confirmed on device: ${dto.device_id} for video: ${dto.video_id}`);
295|    
296|    // Updates the device's last playback time (and last seen time)
297|    await this.prisma.device.updateMany({
298|      where: { deviceId: dto.device_id },
299|      data: {
300|        lastPlayback: new Date(dto.timestamp),
301|        lastSeen: new Date(),
302|      },
303|    });
304|
305|    // Record the playback event in the database for tracking/analytics
306|    return this.prisma.playbackEvent.create({
307|      data: {
308|        deviceId: dto.device_id,
309|        videoId: dto.video_id,
310|        eventType: 'play_confirm',
311|        timestamp: new Date(dto.timestamp),
312|        lat: dto.lat,
313|        lng: dto.lng,
314|        isSimulated: dto.isSimulated || false,
315|        verified: false
316|      },
317|    });
318|  }
319|
320|  async syncDeviceCampaigns(dto: SyncDeviceDto) {
321|    const { deviceId, lat, lng, batteryLevel, lastHash } = dto;
322|
323|    // 🔒 Block sync for PENDING devices
324|    const deviceCheck = await this.prisma.device.findUnique({ where: { deviceId } });
325|    if (!deviceCheck) {
326|      return { blocked: true, reason: 'awaiting_approval', media_assets: [] };
327|    }
328|    if (deviceCheck.status === BUSINESS_RULES.STATUS.DEVICE.INITIAL) {
329|      this.logger.log(`⏳ Sync blocked for PENDING device: ${deviceId}`);
330|      return { blocked: true, reason: 'awaiting_approval', media_assets: [] };
331|    }
332|
333|    // 1. Update Telemetry & Health
334|    const device = await this.prisma.device.update({
335|      where: { deviceId },
336|      data: {
337|        lastLat: lat,
338|        lastLng: lng,
339|        batteryLevel: batteryLevel,
340|        lastSync: new Date(),
341|        isOnline: true,
342|      },
343|    });
344|
345|    // 2. Alert Logic (Critical Inactivity & Battery)
346|    if (batteryLevel !== undefined && batteryLevel < 15) {
347|      this.logger.warn(`🚨 [CRITICAL_BATTERY] Device ${deviceId} at ${batteryLevel}%`);
348|      await this.prisma.notification.create({
349|        data: {
350|          title: 'Batería Crítica detectada',
351|          message: `La tablet ${device.taxiNumber || deviceId} reporta un nivel crítico (${batteryLevel}%).`,
352|          type: 'CRITICAL',
353|          category: 'DEVICE',
354|          entityId: deviceId,
355|        }
356|      });
357|    }
358|
359|    // Detect recovery from long offline (Re-entry alert)
360|    const threeDaysMs = 3 * 24 * 60 * 60 * 1000;
361|    if (deviceCheck.lastSeen && (new Date().getTime() - deviceCheck.lastSeen.getTime() > threeDaysMs)) {
362|      await this.prisma.notification.create({
363|        data: {
364|          title: 'Dispositivo Recuperado (+3D Offline)',
365|          message: `La tablet ${device.taxiNumber || deviceId} ha vuelto a conectar tras más de 3 días de inactividad crítica.`,
366|          type: 'SUCCESS',
367|          category: 'DEVICE',
368|          entityId: deviceId,
369|        }
370|      });
371|    }
372|
373|    const { blocked, reason } = await this.checkSubscriptionStatus(deviceId);
374|    if (blocked) return { blocked, reason };
375|
376|    // ============================================
377|    // REMOTE COMMANDS — Fetch pending tasks
378|    // ============================================
379|    const pendingCommands = await this.prisma.deviceCommand.findMany({
380|      where: { 
381|        device: { deviceId }, 
382|        status: 'PENDING',
383|        OR: [
384|          { expiresAt: null },
385|          { expiresAt: { gt: new Date() } }
386|        ]
387|      },
388|      select: {
389|        id: true,
390|        commandType: true,
391|        commandParams: true,
392|      }
393|    });
394|
395|    if (pendingCommands.length > 0) {
396|      this.logger.log(`📤 Sending ${pendingCommands.length} pending commands to Device ${deviceId}`);
397|      // Mark as PROCESSING so we don't send them multiple times if sync is fast
398|      await this.prisma.deviceCommand.updateMany({
399|        where: { id: { in: pendingCommands.map(c => c.id) } },
400|        data: { status: 'PROCESSING' }
401|      });
402|    }
403|
404|    // Capture device city for geofencing
405|    const deviceCity = device.city || 'Santiago';
406|    const payload = await this.campaignService.getActiveSyncVideos(deviceId, deviceCity);
407|
408|    // ============================================
409|    // DELTA SYNC LOGIC
410|    // ============================================
411|    if (lastHash && lastHash === payload.sync_hash) {
412|      this.logger.log(`🔄 Device ${deviceId}: Delta Sync matches (${lastHash}). No update needed.`);
413|      return { 
414|        update: false, 
415|        blocked: false,
416|        sync_hash: payload.sync_hash 
417|      };
418|    }
419|
420|    if (!payload.media_assets || payload.media_assets.length === 0) {
421|      return { 
422|        update: true, 
423|        blocked: false, 
424|        media_assets: [], 
425|        sync_hash: 'empty' 
426|      };
427|    }
428|
429|    this.logger.log(`📥 Device ${deviceId}: New sync payload available (${payload.sync_hash})`);
430|
