{"content": "1|import { Controller, Get, Delete, Param, Post, Put, Body, BadRequestException, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|import { DeviceService } from './device.service';
4|import { BUSINESS_RULES } from '../../common/constants/business-rules';
5|
6|const KIOSK_COMMAND_TYPES = [
7|  'FORCE_SYNC',
8|  'SCREEN_ON',
9|  'SCREEN_OFF',
10|  'SET_BRIGHTNESS',
11|  'SET_VOLUME',
12|  'MUTE',
13|  'UNMUTE',
14|  'LOCK_KIOSK',
15|  'UNLOCK_KIOSK',
16|  'REBOOT',
17|  'RESTART_APP',
18|  'ENABLE_MOTION',
19|  'DISABLE_MOTION',
20|];
21|
22|@Controller('devices')
23|export class DeviceAdminController {
24|  private readonly logger = new Logger(DeviceAdminController.name);
25|
26|  constructor(
27|    private prisma: PrismaService,
28|    private deviceService: DeviceService,
29|  ) { }
30|
31|  // ─── PENDING DEVICE APPROVAL QUEUE ──────────────────────────────────────────
32|
33|  /** List all devices awaiting admin approval */
34|  @Get('pending')
35|  getPendingDevices() {
36|    return this.deviceService.getPendingDevices();
37|  }
38|
39|  /** Admin approves a device → sets it ACTIVE */
40|  @Post(':deviceId/approve')
41|  approveDevice(@Param('deviceId') deviceId: string) {
42|    return this.deviceService.approveDevice(deviceId);
43|  }
44|
45|  /** Admin rejects a device → deletes it */
46|  @Delete(':deviceId/reject')
47|  rejectDevice(@Param('deviceId') deviceId: string) {
48|    return this.deviceService.rejectDevice(deviceId);
49|  }
50|
51|  // Ver los anuncios asignados a un taxi específico
52|  @Get(':deviceId/campaigns')
53|  async getDeviceCampaigns(@Param('deviceId') paramId: string) {
54|    const device = await this.prisma.device.findFirst({
55|      where: { OR: [{ id: paramId }, { deviceId: paramId }] },
56|      select: { id: true }
57|    });
58|
59|    if (!device) return [];
60|
61|    const assignments = await this.prisma.deviceCampaign.findMany({
62|      where: { device_id: device.id },
63|      include: {
64|        campaign: true,
65|      },
66|    });
67|
68|    return assignments.map(a => ({
69|      ...a.campaign,
70|      assigned_at: a.assigned_at
71|    }));
72|  }
73|
74|  // Quitar un anuncio de un taxi específico
75|  @Delete(':deviceId/campaigns/:campaignId')
76|  async removeCampaignFromDevice(
77|    @Param('deviceId') paramDeviceId: string,
78|    @Param('campaignId') campaignId: string
79|  ) {
80|    // Find device by either UUID or Hardware ID
81|    const device = await this.prisma.device.findFirst({
82|      where: { OR: [{ id: paramDeviceId }, { deviceId: paramDeviceId }] },
83|      select: { id: true, deviceId: true }
84|    });
85|
86|    if (!device) {
87|      return { success: false, message: 'Dispositivo no encontrado' };
88|    }
89|
90|    // 1. Borramos en la tabla v2
91|    try {
92|      await this.prisma.deviceCampaign.deleteMany({
93|        where: {
94|          device_id: device.id,
95|          campaign_id: campaignId,
96|        },
97|      });
98|    } catch (e) { }
99|
100|    // 2. Intentamos borrar en la tabla v1 (legacy)
101|    try {
102|      await this.prisma.playlistItem.deleteMany({
103|        where: {
104|          campaignId: campaignId,
105|          deviceId: device.deviceId
106|        }
107|      });
108|    } catch (e) { }
109|
110|    return { success: true, message: 'Campaña removida del dispositivo exitosamente' };
111|  }
112|
113|  // Crear un nuevo dispositivo manualmente
114|  @Post()
115|  async createDevice(@Body() data: { deviceId: string, taxiNumber?: string, city?: string }) {
116|    if (!data.deviceId) throw new BadRequestException('ID de dispositivo (hardware) es obligatorio');
117|
118|    // Check if hardware ID already exists
119|    const existing = await this.prisma.device.findUnique({ where: { deviceId: data.deviceId } });
120|    if (existing) throw new BadRequestException(`El ID ${data.deviceId} ya está registrado`);
121|
122|    return this.prisma.device.create({
123|      data: {
124|        deviceId: data.deviceId,
125|        taxiNumber: data.taxiNumber,
126|        city: data.city || 'Santo Domingo',
127|        status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE,
128|      }
129|    });
130|  }
131|
132|  // Actualizar datos de un dispositivo
133|  @Put(':id')
134|  async updateDevice(
135|    @Param('id') id: string,
136|    @Body() data: { taxiNumber?: string, city?: string, status?: string, driverId?: string | null }
137|  ) {
138|    return this.prisma.device.update({
139|      where: { id },
140|      data: {
141|        taxiNumber: data.taxiNumber,
142|        city: data.city,
143|        status: data.status as any,
144|        ...(data.driverId !== undefined && { driverId: data.driverId }),
145|      },
146|      include: { driver: true }
147|    });
148|  }
149|
150|  // Eliminar un dispositivo completamente
151|  @Delete(':deviceId')
152|  async deleteDevice(@Param('deviceId') deviceId: string) {
153|    // Find device by deviceId (hardware ID) or by UUID
154|    const device = await this.prisma.device.findFirst({
155|      where: { OR: [{ id: deviceId }, { deviceId: deviceId }] }
156|    });
157|    if (!device) return { success: false, message: 'Dispositivo no encontrado' };
158|
159|    const uuid = device.id;
160|    const hwId = device.deviceId;
161|
162|    // Perform atomic deletion of all related telemetry and assignments
163|    try {
164|      return await this.prisma.$transaction(async (tx) => {
165|        // 1. Analytics & Metrics (References by UUID or Hardware ID)
166|        await tx.analyticsEvent.deleteMany({ where: { deviceId: hwId } });
167|        await tx.campaignMetric.deleteMany({ where: { deviceId: uuid } });
168|
169|        // 2. Telemetry & Logs (References by Hardware ID)
170|        await tx.playbackEvent.deleteMany({ where: { deviceId: hwId } });
171|        await tx.deviceHeartbeat.deleteMany({ where: { deviceId: hwId } });
172|        await tx.playlistItem.deleteMany({ where: { deviceId: hwId } });
173|        await tx.driverLocation.deleteMany({ where: { deviceId: hwId } });
174|
175|        // 3. Operational Data (References by UUID or Hardware ID)
176|        await tx.deviceCommand.deleteMany({ where: { deviceId: uuid } });
177|        await tx.deviceCampaign.deleteMany({ where: { device_id: uuid } });
178|        await tx.subscription.deleteMany({ where: { deviceId: hwId } });
179|
180|        // 4. Notifications (References by either ID in string field)
181|        await tx.notification.deleteMany({
182|          where: {
183|            OR: [
184|              { entityId: uuid },
185|              { entityId: hwId }
186|            ]
187|          }
188|        });
189|
190|        // 5. Finally delete the device identity
191|        await tx.device.delete({ where: { id: uuid } });
192|
193|        this.logger.log(`🗑️ Device ${hwId} (${uuid}) completely purged from system.`);
194|        return { success: true, message: `Dispositivo ${hwId} eliminado correctamente` };
195|      });
196|    } catch (error: any) {
197|      this.logger.error(`❌ Failed to delete device ${hwId}: ${error.message}`);
198|      throw new Error(`Error al eliminar nodo: ${error.message}`);
199|    }
200|  }
201|
202|  // Perfil completo del nodo (device + driver + campaigns)
203|  @Get(':deviceId/profile')
204|  async getDeviceProfile(@Param('deviceId') deviceId: string) {
205|    try {
206|      const device = await this.prisma.device.findFirst({
207|        where: { OR: [{ id: deviceId }, { deviceId: deviceId }] },
208|        include: {
209|          driver: true,
210|          campaigns: { include: { campaign: { select: { id: true, name: true, advertiser: true, active: true } } } },
211|        }
212|      });
213|
214|      if (!device) {
215|        this.logger.warn(`🔍 Perfil solicitado para dispositivo inexistente: ${deviceId}`);
216|        return { error: 'Dispositivo no encontrado' };
217|      }
218|
219|      return {
220|        id: device.id,
221|        device_id: device.deviceId,
222|        taxi_number: device.taxiNumber,
223|        city: device.city,
224|        status: device.status,
225|        battery_level: device.batteryLevel,
226|        storage_free: device.storageFree,
227|        app_version: device.appVersion,
228|        last_seen: device.lastSeen,
229|        player_status: device.playerStatus,
230|        driver: device.driver ? {
231|          id: device.driver.id,
232|          fullName: device.driver.fullName,
233|          phone: device.driver.phone,
234|          cedula: device.driver.cedula,
235|          licensePlate: device.driver.licensePlate,
236|          taxiPlate: device.driver.taxiPlate,
237|          subscriptionPaid: device.driver.subscriptionPaid,
238|          status: device.driver.status,
239|        } : null,
240|        campaigns: device.campaigns
241|          .filter(c => c.campaign) // Defensa contra campañas huérfanas
242|          .map(c => ({
243|            id: c.campaign.id,
244|            name: c.campaign.name,
245|            advertiser: c.campaign.advertiser,
246|            active: c.campaign.active,
247|            assigned_at: c.assigned_at,
248|          })),
249|      };
250|    } catch (error: any) {
251|      this.logger.error(`❌ Error fatal cargando perfil de ${deviceId}: ${error.message}`);
252|      return {
253|        error: 'Excepción interna al procesar el perfil',
254|        message: error.message
255|      };
256|    }
257|  }
258|
259|  // Actualizar perfil completo (dispositivo y chofer)
260|  @Put(':deviceId/profile')
261|  async updateDeviceProfile(@Param('deviceId') deviceId: string, @Body() data: any) {
262|    const device = await this.prisma.device.findFirst({
263|      where: { OR: [{ id: deviceId }, { deviceId: deviceId }] },
264|      include: { driver: true }
265|    });
266|
267|    if (!device) throw new BadRequestException('Dispositivo no encontrado');
268|
269|    // Update Device
270|    const updateData: any = {};
271|    if (data.taxi_number !== undefined) updateData.taxiNumber = data.taxi_number;
272|    if (data.status !== undefined) updateData.status = data.status as any;
273|
274|    // Update Driver if exists
275|    if (device.driver) {
276|      updateData.driver = {
277|        update: {
278|          fullName: data.driver_name !== undefined ? data.driver_name : device.driver.fullName,
279|          phone: data.driver_phone !== undefined ? data.driver_phone : device.driver.phone,
280|          subscriptionPaid: data.subscription_paid !== undefined ? data.subscription_paid : device.driver.subscriptionPaid
281|        }
282|      };
283|    } else if (data.driver_name) {
284|      // Create driver if not exists but name is provided
285|      updateData.driver = {
286|        create: {
287|          fullName: data.driver_name,
288|          phone: data.driver_phone || 'N/A',
289|          subscriptionPaid: data.subscription_paid || false,
290|          licensePlate: data.taxi_number || 'N/A',
291|          taxiNumber: data.taxi_number || 'N/A',
292|        }
293|      };
294|    }
295|
296|    const updated = await this.prisma.device.update({
297|      where: { id: device.id },
298|      data: updateData
299|    });
300|
301|    return { success: true, message: 'Perfil actualizado', device: updated };
302|  }
303|
304|  // ── FullyKiosk Remote Commands ──
305|  // Send kiosk management commands to tablet devices via DeviceCommand queue.
306|  // The player's FullyKioskBridge processes these on next sync cycle.
307|
308|  /** Send a command to a single device */
309|  @Post(':deviceId/command')
310|  async sendDeviceCommand(
311|    @Param('deviceId') deviceId: string,
312|    @Body() body: { commandType: string; params?: Record<string, unknown> },
313|  ) {
314|    if (!KIOSK_COMMAND_TYPES.includes(body.commandType)) {
315|      throw new BadRequestException(`Invalid command type: ${body.commandType}. Valid types: ${KIOSK_COMMAND_TYPES.join(', ')}`);
316|    }
317|
318|    const device = await this.prisma.device.findFirst({
319|      where: { OR: [{ id: deviceId }, { deviceId: deviceId }] },
320|    });
321|    if (!device) throw new BadRequestException('Dispositivo no encontrado');
322|
323|    const command = await this.prisma.deviceCommand.create({
324|      data: {
325|        deviceId: device.id,
326|        commandType: body.commandType,
327|        commandParams: body.params ? JSON.stringify(body.params) : null,
328|        status: 'PENDING',
329|        expiresAt: new Date(Date.now() + BUSINESS_RULES.COMMAND_TTL_DAYS * 24 * 3600 * 1000),
330|      },
331|    });
332|
333|    // Wake the device via Supabase Realtime
334|    this.logger.log(`📤 Command ${body.commandType} queued for device ${device.deviceId}`);
335|    return { success: true, command };
336|  }
337|
338|  /** Broadcast a command to all devices in a fleet or city */
339|  @Post('broadcast')
340|  async broadcastCommand(
341|    @Body() body: { commandType: string; params?: Record<string, unknown>; city?: string; fleet?: string },
342|  ) {
343|    if (!KIOSK_COMMAND_TYPES.includes(body.commandType)) {
344|      throw new BadRequestException(`Invalid command type: ${body.commandType}`);
345|    }
346|
347|    const where: any = { status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE };
348|    if (body.city) where.city = body.city;
349|    if (body.fleet) where.fleet = body.fleet;
350|
351|    const devices = await this.prisma.device.findMany({
352|      where,
353|      select: { id: true, deviceId: true },
354|    });
355|
356|    if (devices.length === 0) {
357|      return { success: false, message: 'No devices found for this filter' };
358|    }
359|
360|    const commands = await this.prisma.deviceCommand.createMany({
361|      data: devices.map(d => ({
362|        deviceId: d.id,
363|        commandType: body.commandType,
364|        commandParams: body.params ? JSON.stringify(body.params) : null,
365|        status: 'PENDING',
366|        expiresAt: new Date(Date.now() + BUSINESS_RULES.COMMAND_TTL_DAYS * 24 * 3600 * 1000),
367|      })),
