104|  async createCampaign(dto: CreateCampaignDto, user?: AuthUser) {
105|    const isAdmin = user?.role === 'ADMIN';
106|    const isAdvertiser = user?.role === 'ADVERTISER';
107|    let assignedAdvertiser = dto.advertiser;
108|    let assignedAdvertiserId = dto.advertiser_id; // Support explicit ID from DTO
109|    let initialStatus = dto.active ? 'ACTIVE' : 'DRAFT';
110|
111|    if (isAdvertiser && user?.entityId) {
112|      assignedAdvertiserId = user.entityId;
113|      // We can optionally fetch the company name to sync the 'advertiser' field (v1 fallback)
114|      const advertiser = await this.prisma.advertiser.findUnique({ where: { id: user.entityId } });
115|      assignedAdvertiser = advertiser?.companyName || assignedAdvertiser;
116|      initialStatus = 'PENDING_REVIEW';
117|    } else if (!isAdmin && user?.email && !assignedAdvertiserId) {
118|      const advertiser = await this.prisma.advertiser.findUnique({ where: { email: user.email } });
119|      if (advertiser) {
120|        assignedAdvertiserId = advertiser.id;
121|        assignedAdvertiser = advertiser.companyName;
122|      }
123|      initialStatus = 'PENDING_REVIEW';
124|    }
125|
126|    const campaign = await this.prisma.campaign.create({
127|      data: {
128|        name: dto.name,
129|        advertiser: assignedAdvertiser,
130|        advertiserId: assignedAdvertiserId,
131|        startDate: new Date(dto.start_date),
132|        endDate: new Date(dto.end_date),
133|        active: initialStatus === 'ACTIVE',
134|        status: initialStatus,
135|        targetImpressions: dto.target_impressions || 0,
136|        budget: dto.budget || 0,
137|        targetAll: dto.target_all !== undefined ? dto.target_all : false,
138|        targetCity: dto.target_city || 'Global',
139|        category: dto.category || 'General',
140|        whatsapp: dto.whatsapp,
141|        instagram: dto.instagram,
142|        facebook: dto.facebook,
143|        websiteUrl: dto.websiteUrl,
144|        pedidosYaUrl: dto.pedidosYaUrl,
145|        uberEatsUrl: dto.uberEatsUrl,
146|      } as any,
147|    });
148|
149|    // TAD-ADMIN: Distribución Inteligente de Inventario
150|    // Si no se pasaron dispositivos pero hay ciudad, auto-asignamos usando prioridad ORO > PLATA > BASE
151|    let devicesToAssign = dto.target_devices || [];
152|
153|    if (devicesToAssign.length === 0 && !dto.target_all && dto.target_city) {
154|      this.logger.log(`🤖 Auto-asignando dispositivos para campaña ${campaign.id} en ${dto.target_city}`);
155|      const limit = Math.floor((dto.budget || 3000) / 3000) || 10; // Estimado de pantallas según presupuesto
156|      const optimalDevices = await this.getOptimalDevicesForCampaign(dto.target_city, limit);
157|      devicesToAssign = optimalDevices.map(d => d.deviceId);
158|    }
159|
160|    if (devicesToAssign.length > 0) {
161|      await this.assignCampaignToDevices(campaign.id, devicesToAssign);
162|    }
163|
164|    if (campaign.status === 'ACTIVE') {
165|      await this.prisma.refreshActiveCampaignsView();
166|      this.supabaseService.broadcastEvent('fleet_sync', 'WAKE_UP_CALL', {
167|        reason: 'campaign_created',
168|        campaignId: campaign.id
169|      }).catch(() => { });
170|    }
171|
172|    return campaign;
