175|  async assignCampaignToDevices(campaignId: string, idOrHwIds: string[]) {
176|    // 1. Fetch devices using either UUID (id) or Hardware ID (deviceId)
177|    const devices = await this.prisma.device.findMany({
178|      where: {
179|        OR: [
180|          { id: { in: idOrHwIds } },
181|          { deviceId: { in: idOrHwIds } }
182|        ]
183|      },
184|      select: { id: true, deviceId: true, _count: { select: { campaigns: true } } }
185|    });
186|
187|    if (devices.length === 0 && idOrHwIds.length > 0) {
188|      this.logger.warn(`⚠️ No devices found for ${idOrHwIds.length} provided IDs.`);
189|    }
190|
191|    // 2. Identify available devices (respecting the limit)
192|    const availableDevices = devices.filter(d => d._count.campaigns < BUSINESS_RULES.MAX_CAMPAIGNS_PER_DRIVER);
193|    const skippedCount = devices.length - availableDevices.length;
194|
195|    // 3. TRANSACTIONAL UPDATE: Clean old and insert new
196|    return await this.prisma.$transaction(async (tx) => {
197|      // Clear all existing assignments for this campaign
198|      await tx.playlistItem.deleteMany({ where: { campaignId } });
199|      await tx.deviceCampaign.deleteMany({ where: { campaign_id: campaignId } });
200|
201|      // Update the campaign's updatedAt to trigger cache invalidation
202|      await tx.campaign.update({
203|        where: { id: campaignId },
204|        data: { updatedAt: new Date() }
205|      });
206|
207|      if (availableDevices.length === 0) return { count: 0, skipped: skippedCount };
208|
209|      // Create new assignments (V1 Legacy & V2 Core)
210|      const dataV1 = availableDevices.map(d => ({ campaignId, deviceId: d.deviceId }));
211|      const dataV2 = availableDevices.map(d => ({ campaign_id: campaignId, device_id: d.id }));
212|
213|      await tx.playlistItem.createMany({ data: dataV1 });
214|      await tx.deviceCampaign.createMany({ data: dataV2 });
215|
216|      // Create FORCE_SYNC commands to wake tablets and trigger instant sync
217|      // We send to UUID (id) because DeviceCommand relation uses UUID
218|      const commands = availableDevices.map(d => ({
219|        deviceId: d.id,
220|        commandType: 'FORCE_SYNC',
221|        commandParams: JSON.stringify({ reason: 'campaign_assigned', campaignId, deviceId: d.deviceId }),
222|        status: 'PENDING',
223|        expiresAt: new Date(Date.now() + 24 * 3600 * 1000)
224|      }));
225|      await tx.deviceCommand.createMany({ data: commands });
226|
227|      // BROADCAST REALTIME: Send WAKE_UP_CALL to fleet_sync channel
228|      this.supabaseService.broadcastEvent('fleet_sync', 'WAKE_UP_CALL', {
229|        reason: 'campaign_assigned',
230|        campaignId,
231|        targets: availableDevices.map(d => d.deviceId)
232|      }).catch(e => this.logger.warn(`Realtime broadcast failed: ${e.message}`));
233|
234|      // SRE Optimization: Refresh view so heartbeats get the new state immediately
235|      this.prisma.refreshActiveCampaignsView().catch(e => this.logger.error(`View refresh failed: ${e.message}`));
236|
237|      return { count: availableDevices.length, skipped: skippedCount };
238|    });
239|  }
