367|            status: 'PENDING',
368|            expiresAt: new Date(Date.now() + 24 * 3600 * 1000)
369|          }))
370|        });
371|      }
372|    }
373|
374|    // BROADCAST WAKE_UP_CALL only if not rendering
375|    const isRendering = dto.status === 'RENDERING';
