406|   * Returns a payload of videos specifically assigned to this device (Manual Distribution)
407|   */
408|  async getActiveSyncVideos(deviceIdOrUuid: string, deviceCity?: string) {
409|    const now = new Date();
410|    this.logger.log(`🕒 Sync Internal Clock: ${now.toISOString()} (${now.getTime()})`);
411|
412|    // 1. Resolve Identity: Find the device by Hardware ID or UUID
413|    const device = await this.prisma.device.findFirst({
414|      where: { OR: [{ id: deviceIdOrUuid }, { deviceId: deviceIdOrUuid }] },
415|      select: { id: true, deviceId: true, city: true, driverId: true }
416|    });
417|
418|    if (!device) {
419|      this.logger.warn(`⚠️ getActiveSyncVideos: Device '${deviceIdOrUuid}' NOT FOUND in DB. Check if registerDevice was called first.`);
420|      return { version: 0, sync_hash: 'not-found', media_assets: [] };
421|    }
422|
423|    const uuid = device.id;
424|    const hwId = device.deviceId;
425|    const city = deviceCity || device.city || 'Santiago';
426|    const driverId = device.driverId;
427|    this.logger.log(`🔎 Sync for device: hwId=${hwId}, uuid=${uuid}, city=${city}, driverId=${driverId || 'none'}`);
428|
429|    let activeCampaigns: any[] = [];
430|
431|    try {
432|      // 2. MASTER SYNC (Materialized View)
433|      // Pre-calculated targeting avoids complex joins in heartbeats.
434|      const results: any[] = await this.prisma.$queryRaw`
435|        SELECT campaign_id FROM mv_active_campaigns
436|        WHERE active = true 
437|          AND start_date <= NOW() 
438|          AND end_date >= NOW()
439|          AND (
440|            target_all = true OR 
441|            target_city = ${city} OR
442|            target_cities::text LIKE ${`%${city}%`} OR
