{"content": "1|// ─── TAD DOOH Player — CacheManager ───
2|// IndexedDB-based video blob caching for offline resilience.
3|// Falls back to Cache API then network when IndexedDB is unavailable.
4|
5|import type { MediaAsset, CachedVideo } from './types';
6|import env from './config';
7|
8|const DB_NAME = 'tad_video_cache';
9|const DB_VERSION = 1;
10|const STORE_NAME = 'videos';
11|
12|export class CacheManager {
13|  private dbReady: Promise<IDBDatabase>;
14|  // Fix #6: Track active blob URLs to revoke them when assets are evicted.
15|  // Without this, blob URLs created via URL.createObjectURL() leak memory
16|  // across multiple sync cycles. The browser keeps the underlying blob alive
17|  // until either the URL is revoked or the document is unloaded.
18|  private activeObjectUrls = new Map<string, string>();
19|
20|  constructor() {
21|    this.dbReady = this.openDB();
22|  }
23|
24|  private async openDB(): Promise<IDBDatabase> {
25|    return new Promise((resolve, reject) => {
26|      const request = indexedDB.open(DB_NAME, DB_VERSION);
27|      request.onupgradeneeded = () => {
28|        const db = request.result;
29|        if (!db.objectStoreNames.contains(STORE_NAME)) {
30|          db.createObjectStore(STORE_NAME, { keyPath: 'url' });
31|        }
32|      };
33|      request.onsuccess = () => resolve(request.result);
34|      request.onerror = () => reject(request.error);
35|    });
36|  }
37|
38|  async getVideoSource(asset: MediaAsset): Promise<string> {
39|    // 1. Check IndexedDB
40|    const cached = await this.getFromIndexedDB(asset.url);
41|    if (cached) {
42|      if (asset.checksum && cached.checksum !== asset.checksum) {
43|        // Integrity mismatch — evict stale entry
44|        await this.evict(asset.url);
45|      } else {
46|        // Fix #6: Revoke existing blob URL before creating a new one
47|        // (defensive: prevents duplicate URLs for the same asset key)
48|        const existingUrl = this.activeObjectUrls.get(asset.url);
49|        if (existingUrl) {
50|          URL.revokeObjectURL(existingUrl);
51|        }
52|        const objectUrl = URL.createObjectURL(cached.blob);
53|        this.activeObjectUrls.set(asset.url, objectUrl);
54|        return objectUrl;
55|      }
56|    }
57|
58|    // 2. Check Cache API (browser cache)
59|    try {
60|      const cache = await caches.open('tad-player-videos');
61|      const response = await cache.match(asset.url);
62|      if (response) {
63|        const blob = await response.blob();
64|        if (blob.size <= env.MAX_VIDEO_SIZE_BYTES) {
65|          await this.saveToIndexedDB(asset, blob);
66|          const existingUrl = this.activeObjectUrls.get(asset.url);
67|          if (existingUrl) {
68|            URL.revokeObjectURL(existingUrl);
69|          }
70|          const objectUrl = URL.createObjectURL(blob);
71|          this.activeObjectUrls.set(asset.url, objectUrl);
72|          return objectUrl;
73|        }
74|      }
75|    } catch {
76|      // Cache API unavailable — proceed to network
77|    }
78|
79|    // 3. Network fetch (online-only path)
80|    try {
81|      const response = await fetch(asset.url);
82|      if (!response.ok) throw new Error(`HTTP ${response.status}`);
83|      const blob = await response.blob();
84|      if (blob.size <= env.MAX_VIDEO_SIZE_BYTES) {
85|        await this.saveToIndexedDB(asset, blob);
86|        // Also store in Cache API for dual-layer resilience
87|        try {
88|          const cache = await caches.open('tad-player-videos');
89|          await cache.put(asset.url, new Response(blob));
90|        } catch { /* non-critical */ }
91|        const existingUrl = this.activeObjectUrls.get(asset.url);
92|        if (existingUrl) {
93|          URL.revokeObjectURL(existingUrl);
94|        }
95|        const objectUrl = URL.createObjectURL(blob);
96|        this.activeObjectUrls.set(asset.url, objectUrl);
97|        return objectUrl;
98|      }
99|    } catch (err) {
100|      console.error(`[CacheManager] Network fetch failed for ${asset.filename}:`, err);
101|      throw err;
102|    }
103|
104|    throw new Error(`No video source available for ${asset.filename}`);
105|  }
106|
107|  async cacheVideos(assets: MediaAsset[]): Promise<{ cached: number; failed: number }> {
108|    let cached = 0;
109|    let failed = 0;
110|
111|    for (const asset of assets) {
112|      try {
113|        const existing = await this.getFromIndexedDB(asset.url);
114|        if (existing && existing.checksum === asset.checksum) {
115|          cached++;
116|          continue; // Already cached and valid
117|        }
118|        await this.getVideoSource(asset); // Downloads + caches
119|        cached++;
120|      } catch {
121|        failed++;
122|      }
123|    }
124|
125|    return { cached, failed };
126|  }
127|
128|  async hasMissingAssets(assets: MediaAsset[]): Promise<boolean> {
129|    for (const asset of assets) {
130|      const cached = await this.getFromIndexedDB(asset.url);
131|      if (!cached || (asset.checksum && cached.checksum !== asset.checksum)) {
132|        return true;
133|      }
134|    }
135|    return false;
136|  }
137|
138|  async evictStaleAssets(currentAssets: MediaAsset[]): Promise<number> {
139|    const db = await this.dbReady;
140|    const tx = db.transaction(STORE_NAME, 'readonly');
141|    const store = tx.objectStore(STORE_NAME);
142|    const allKeys = await new Promise<string[]>(resolve => {
143|      const req = store.getAllKeys();
144|      req.onsuccess = () => resolve(req.result as string[]);
145|    });
146|
147|    const currentUrls = new Set(currentAssets.map(a => a.url));
148|    let evicted = 0;
149|
150|    for (const key of allKeys) {
151|      if (!currentUrls.has(key as string)) {
152|        await this.evict(key as string);
153|        evicted++;
154|      }
155|    }
156|    return evicted;
157|  }
158|
159|  private async getFromIndexedDB(url: string): Promise<CachedVideo | null> {
160|    const db = await this.dbReady;
161|    return new Promise(resolve => {
162|      const tx = db.transaction(STORE_NAME, 'readonly');
163|      const store = tx.objectStore(STORE_NAME);
164|      const req = store.get(url);
165|      req.onsuccess = () => resolve(req.result || null);
166|      req.onerror = () => resolve(null);
167|    });
168|  }
169|
170|  private async saveToIndexedDB(asset: MediaAsset, blob: Blob): Promise<void> {
171|    const db = await this.dbReady;
172|    return new Promise((resolve, reject) => {
173|      const tx = db.transaction(STORE_NAME, 'readwrite');
174|      const store = tx.objectStore(STORE_NAME);
175|      const entry: CachedVideo = {
176|        url: asset.url,
177|        blob,
178|        checksum: asset.checksum || asset.hashMd5 || 'no-checksum',
179|        cachedAt: Date.now(),
180|        size: blob.size,
181|      };
182|      const req = store.put(entry);
183|      req.onsuccess = () => resolve();
184|      req.onerror = () => reject(req.error);
185|    });
186|  }
187|
188|  private async evict(url: string): Promise<void> {
189|    const db = await this.dbReady;
190|
191|    // Fix #6: Liberar el objeto URL del blob antes de borrar el registro.
192|    // Sin esto, el blob permanece en RAM hasta que se descargue el documento.
193|    const activeUrl = this.activeObjectUrls.get(url);
194|    if (activeUrl) {
195|      URL.revokeObjectURL(activeUrl);
196|      this.activeObjectUrls.delete(url);
197|    }
198|
199|    return new Promise(resolve => {
200|      const tx = db.transaction(STORE_NAME, 'readwrite');
201|      const store = tx.objectStore(STORE_NAME);
202|      const req = store.delete(url);
203|      req.onsuccess = () => resolve();
204|      req.onerror = () => resolve(); // Non-critical
205|    });
206|  }
207|}
